// ─── Utilities ────────────────────────────────────────────────────────────────
const uid    = () => Math.random().toString(36).slice(2, 9);
// getAb removed — no more abilityId lookup
const tiltOf = card => (((card.id || "").charCodeAt(0) % 7) - 3) * 1.4;
const hueOf  = card => ((card.name || "X").charCodeAt(0) * 47 + 180) % 360;
const emojiOf= hue  => String.fromCodePoint(0x1F300 + (hue % 80));

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ─── Game Logic ───────────────────────────────────────────────────────────────
function buildDeck(playerCards) {
  const pool = [...playerCards];
  let i = 0;
  while (pool.length < 8) {
    pool.push({ ...SPREADSHEET_CARDS[i % SPREADSHEET_CARDS.length], id: uid() });
    i++;
  }
  return shuffle(pool.slice(0, 12));
}

function initGame(playerCards) {
  const pDeck = buildDeck(playerCards);
  const aDeck = buildDeck(shuffle([...SPREADSHEET_CARDS]).slice(0, 12));
  return {
    turn: 1, phase: "shuffle", bonusDraw: 0,
    playerHand: [], playerDeck: pDeck,
    _fullPlayerDeck: pDeck,
    aiHand: aDeck.slice(0, HAND_SIZE), aiDeck: aDeck.slice(HAND_SIZE),
    playerDiscard: [], aiDiscard: [],
    playerDestroyed: [], aiDestroyed: [],
    zones: ZONES.map(z => ({ ...z, pCards: [], aCards: [] })),
    playerPlaysThisTurn: [],
    aiPlaysThisTurn: [],
    revealedIds: [],
    priority: Math.random() < 0.5 ? "player" : "ai",
  };
}

function applyReveal(card, zoneIdx, state, isPlayer) {
  // Cosmo blocks On Reveal abilities at this location (opponent's cards only)
  if (state.zones[zoneIdx]._cosmoActive) {
    const cosmoOwner = state.zones[zoneIdx]._cosmoSide; // side that played Cosmo
    const cardSide   = isPlayer ? "player" : "ai";
    // Block the OPPONENT of whoever played Cosmo
    if (cosmoOwner && cardSide !== cosmoOwner) return { state, fx: [] };
  }
  const handler = card.snapName && SNAP_HANDLERS[card.snapName];
  if (!handler) return { state, fx: [] };
  const result = handler(state, card, zoneIdx, isPlayer) || {};
  return { state: result.state || state, fx: result.fx || [] };
}

// displayClout: base power + Ongoing modifiers baked in at render time.
// state is optional — pass it to enable cross-zone Ongoing checks.
function displayClout(card, myCards, state, isPlayer) {
  let c = card.clout;
  // Ka-Zar: 1-cost cards on same side get +1
  if (myCards) {
    const hasKazar = myCards.some(x => x.snapName === "Ka-Zar");
    if (hasKazar && card.energy === 1 && card.snapName !== "Ka-Zar") c += 1;
  }
  return Math.max(0, c);
}

// zonePower: sum display power of all cards in a zone-side array.
// Also applies cross-card Ongoing effects (Iron Man, Blue Marvel, Klaw, Punisher).
// Accepts optional (state, isPlayer, zIdx) for cross-zone lookups.
function zonePower(cards, state, isPlayer, zIdx) {
  let base = cards.reduce((s, c) => s + displayClout(c, cards, state, isPlayer), 0);
  if (!state) return base;

  const sideKey = isPlayer ? "pCards" : "aCards";
  const oppKey  = isPlayer ? "aCards" : "pCards";

  // Iron Man: double TOTAL power at this location
  const hasIronMan = cards.some(c => c.snapName === "Iron Man");
  if (hasIronMan) base = base * 2;

  // Blue Marvel: +1 to every OTHER card (add count of non-BlueMarvel cards)
  const hasBlueMarvels = cards.filter(c => c.snapName === "Blue Marvel").length;
  if (hasBlueMarvels) base += hasBlueMarvels * (cards.length - hasBlueMarvels);

  // Punisher: +1 per enemy card at this location
  const hasPunisher = cards.some(c => c.snapName === "Punisher");
  if (hasPunisher && zIdx !== undefined) {
    const enemyCount = state.zones[zIdx][oppKey].length;
    base += enemyCount;
  }

  // Klaw: the location to the RIGHT of Klaw gets +7 (handled in caller side)
  return base;
}

// klawBonus: call when computing zone power — returns extra from Klaw at left zone
function klawBonusForZone(state, isPlayer, zIdx) {
  if (zIdx === 0) return 0;
  const sideKey = isPlayer ? "pCards" : "aCards";
  const leftZone = state.zones[zIdx - 1];
  return leftZone[sideKey].some(c => c.snapName === "Klaw") ? 7 : 0;
}

// Apply Death cost reduction: card costs 1 less per destroyed card this game.
function deathReducedCost(card, destroyedCount) {
  if (!destroyedCount) return card.energy;
  return Math.max(0, (card.energy||0) - destroyedCount);
}

function resolveGame(state) {
  let s = JSON.parse(JSON.stringify(state));
  const { pPlay, aPlay } = s.pending || {};
  const place = (cardId, zoneIdx, hand, zoneKey) => {
    const ci = hand.findIndex(c => c.id === cardId); if (ci === -1) return null;
    const card = hand.splice(ci, 1)[0]; s.zones[zoneIdx][zoneKey].push(card); return card;
  };
  if (pPlay) { const card = place(pPlay.cardId, pPlay.zoneIdx, s.playerHand, "pCards"); if (card) s = applyReveal(card, pPlay.zoneIdx, s, true).state; }
  if (aPlay) { const card = place(aPlay.cardId, aPlay.zoneIdx, s.aiHand, "aCards");     if (card) s = applyReveal(card, aPlay.zoneIdx, s, false).state; }
  s.pending = null;
  if (s.turn >= TURNS) { s.phase = "end"; }
  else {
    s.turn += 1; s.phase = "play";
    const draws = 1 + (s.bonusDraw || 0); s.bonusDraw = 0;
    for (let i = 0; i < draws; i++) {
      if (s.playerDeck.length) s.playerHand.push(s.playerDeck.shift());
      if (s.aiDeck.length)     s.aiHand.push(s.aiDeck.shift());
    }
  }
  return s;
}

/**
 * End-of-turn resolution: AI plays its card, all this-turn onReveal abilities
 * trigger (player's already-placed card + AI's freshly-placed card), then
 * draw cards and advance to next turn.
 *
 * The player's card is already in zones[zoneIdx].pCards before this is called
 * (placed during the drag). game.playerPlay records {cardId, zoneIdx} so we
 * know which card to fire onReveal on.
 */


// ════════════════════════════════════════════════════════════════════
// Marvel-Snap-style priority/winner calculation:
//   1. Whoever WINS THE MOST LOCATIONS has priority/wins.
//   2. Tied locations → whoever has the BIGGER WINNING MARGIN at any single
//      location takes priority (e.g. won 7-vs-4 beats won 5-vs-4).
//   3. Still tied → higher TOTAL POWER across all 3 zones.
//   4. Total tie → keep current priority (or random for first turn).
// ════════════════════════════════════════════════════════════════════
function computePriority(state, current = null) {
  let pWins = 0, aWins = 0, pTotal = 0, aTotal = 0;
  let pBigMargin = 0, aBigMargin = 0;
  for (let zi = 0; zi < state.zones.length; zi++) {
    const z = state.zones[zi];
    const pp = zonePower(z.pCards, state, true,  zi) + klawBonusForZone(state, true,  zi);
    const ap = zonePower(z.aCards, state, false, zi) + klawBonusForZone(state, false, zi);
    pTotal += pp; aTotal += ap;
    if (pp > ap) { pWins++; pBigMargin = Math.max(pBigMargin, pp - ap); }
    else if (ap > pp) { aWins++; aBigMargin = Math.max(aBigMargin, ap - pp); }
  }
  if (pWins !== aWins) return pWins > aWins ? "player" : "ai";
  if (pBigMargin !== aBigMargin) return pBigMargin > aBigMargin ? "player" : "ai";
  if (pTotal !== aTotal) return pTotal > aTotal ? "player" : "ai";
  return current || (Math.random() < 0.5 ? "player" : "ai");
}

// End-of-game winner — same rules but allows a true "draw" if everything ties.
function computeWinner(state) {
  let pWins = 0, aWins = 0, pTotal = 0, aTotal = 0;
  let pBigMargin = 0, aBigMargin = 0;
  for (let zi = 0; zi < state.zones.length; zi++) {
    const z = state.zones[zi];
    const pp = zonePower(z.pCards, state, true,  zi) + klawBonusForZone(state, true,  zi);
    const ap = zonePower(z.aCards, state, false, zi) + klawBonusForZone(state, false, zi);
    pTotal += pp; aTotal += ap;
    if (pp > ap) { pWins++; pBigMargin = Math.max(pBigMargin, pp - ap); }
    else if (ap > pp) { aWins++; aBigMargin = Math.max(aBigMargin, ap - pp); }
  }
  if (pWins !== aWins) return pWins > aWins ? "player" : "ai";
  if (pBigMargin !== aBigMargin) return pBigMargin > aBigMargin ? "player" : "ai";
  if (pTotal !== aTotal) return pTotal > aTotal ? "player" : "ai";
  return "draw";
}

function endTurnResolve(state) {
  let s = JSON.parse(JSON.stringify(state));

  // 1. AI plays as many cards as it can afford (greedy: play random affordable)
  const aiBudget = s.turn;
  let aiSpent = 0;
  const aiPlays = [];
  for (let attempt = 0; attempt < 3 && s.aiHand.length; attempt++) {
    const affordable = s.aiHand.filter(c => (c.energy ?? c.clout) <= aiBudget - aiSpent);
    if (!affordable.length) break;
    // Only consider zones with room
    const openZones = [0, 1, 2].filter(zi => s.zones[zi].aCards.length < MAX_PER_SIDE);
    if (!openZones.length) break;
    const pick = affordable[Math.floor(Math.random() * affordable.length)];
    const zoneIdx = openZones[Math.floor(Math.random() * openZones.length)];
    const ci = s.aiHand.findIndex(c => c.id === pick.id);
    if (ci === -1) break;
    const card = s.aiHand.splice(ci, 1)[0];
    s.zones[zoneIdx].aCards.push(card);
    aiSpent += card.energy ?? card.clout;
    aiPlays.push({ cardId: card.id, zoneIdx });
  }

  // 2. Fire onReveal abilities — player's plays first, then AI's, in placement order
  for (const p of (s.playerPlaysThisTurn || [])) {
    const card = s.zones[p.zoneIdx].pCards.find(c => c.id === p.cardId);
    if (card) s = applyReveal(card, p.zoneIdx, s, true).state;
  }
  for (const p of aiPlays) {
    const card = s.zones[p.zoneIdx].aCards.find(c => c.id === p.cardId);
    if (card) s = applyReveal(card, p.zoneIdx, s, false).state;
  }
  s.playerPlaysThisTurn = [];

  // 3. Advance turn / end game
  if (s.turn >= TURNS) {
    s.phase = "end";
  } else {
    s.turn += 1;
    s.phase = "play";
    const draws = 1 + (s.bonusDraw || 0);
    s.bonusDraw = 0;
    for (let i = 0; i < draws; i++) {
      if (s.playerDeck.length) s.playerHand.push(s.playerDeck.shift());
      if (s.aiDeck.length)     s.aiHand.push(s.aiDeck.shift());
    }
  }
  return s;
}

function getResults(state) {
  return state.zones.map((z, zi) => {
    const pp = zonePower(z.pCards, state, true,  zi) + klawBonusForZone(state, true,  zi);
    const ap = zonePower(z.aCards, state, false, zi) + klawBonusForZone(state, false, zi);
    return { pp, ap, winner: pp > ap ? "player" : ap > pp ? "ai" : "tie" };
  });
}

function aiDecide(game) {
  if (!game.aiHand.length) return null;
  return { cardId: game.aiHand[Math.floor(Math.random() * game.aiHand.length)].id, zoneIdx: Math.floor(Math.random() * 3) };
}

// ─── CSS ──────────────────────────────────────────────────────────────────────
const GLOBAL_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@400;600;700&family=Space+Mono:wght@700&display=swap');
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #080810; --bg2: #10101e; --bg3: #181828;
    --border: rgba(255,255,255,0.07);
    --neon: #b4ff4f; --hot: #ff5fba; --ice: #5fd4ff;
    --text: #dde0f5; --muted: #5a5a80;
    --r: 14px;
    --f-display: 'Bangers', 'Impact', sans-serif;            /* card names, titles, big bold callouts */
    --f-head: 'Inter', system-ui, sans-serif;                /* UI text, ability descriptions */
    --f-mono: 'Orbitron', 'SF Mono', monospace;              /* numbers, badges, energy/power */
  }
  html, body, #root { height: 100%; }
  body { background: var(--bg); color: var(--text); font-family: var(--f-head); overflow-x: hidden; }
  /* Bounded height so flex children with overflow can scroll properly.
     min-height was causing the WHOLE PAGE to scroll instead of the grid,
     which broke iOS touch handling (only edge swipes registered). */
  .screen {
    height: 100vh;
    height: 100dvh;
    display: flex; flex-direction: column;
    overflow: hidden;
  }
  .screen-header { display:flex; align-items:center; gap:12px; padding:12px 18px; border-bottom:1px solid var(--border); background:var(--bg2); }
  .screen-header h2 { flex:1; font-size:1.2rem; font-weight:600; }
  .btn { font-family:var(--f-head); font-weight:600; font-size:1rem; border:none; border-radius:10px; padding:8px 16px; cursor:pointer; user-select:none; transition:transform 0.1s, filter 0.15s; }
  .btn:active { transform:scale(0.93); }
  .btn-primary   { background:var(--neon); color:#060608; }
  .btn-primary:hover { filter:brightness(1.1); }
  .btn-secondary { background:var(--bg3); color:var(--text); border:1px solid var(--border); }
  .btn-secondary:hover { border-color:rgba(255,255,255,0.18); }
  .btn-ghost     { background:transparent; color:var(--muted); }
  .btn-ghost:hover { color:var(--text); }
  .btn-danger    { background:rgba(255,55,75,0.16); color:#ff6868; }
  .btn-danger:hover { background:rgba(255,55,75,0.26); }
  .btn-sm  { padding:5px 10px; font-size:0.82rem; border-radius:7px; }
  .btn-big { padding:14px 44px; font-size:1.3rem; border-radius:14px; }

  .home-screen { align-items:center; justify-content:center; gap:52px; background:radial-gradient(ellipse at 50% 55%, #16082e 0%, var(--bg) 68%); }
  .home-logo { text-align:center; }
  .home-logo h1 { font-size:clamp(5.5rem,22vw,11rem); font-weight:700; line-height:0.9; color:var(--neon); letter-spacing:-0.03em; text-shadow:0 0 50px rgba(180,255,79,0.45),0 0 120px rgba(180,255,79,0.18); animation:logo-float 3.2s ease-in-out infinite; }
  @keyframes logo-float { 0%,100%{transform:translateY(0) rotate(-1deg)} 50%{transform:translateY(-10px) rotate(1deg);text-shadow:0 0 70px rgba(180,255,79,0.65),0 0 160px rgba(180,255,79,0.25)} }
  .home-sub { font-size:0.95rem; color:var(--muted); margin-top:10px; letter-spacing:0.07em; text-transform:lowercase; }
  .home-actions { display:flex; flex-direction:column; align-items:center; gap:14px; }

  /* ── Collection grid ── */
  .collection-toolbar { display:flex; gap:8px; padding:12px 14px; align-items:center; background:var(--bg2); border-bottom:1px solid var(--border); }
  .search-input { background:var(--bg3); border:1.5px solid var(--border); color:var(--text); border-radius:9px; padding:7px 12px; font-family:var(--f-head); font-size:0.9rem; outline:none; flex:1; transition:border-color 0.18s; }
  .search-input:focus { border-color:var(--neon); }
  .filter-tabs { display:flex; gap:5px; }
  .filter-tab { background:var(--bg3); border:1.5px solid var(--border); color:var(--muted); border-radius:8px; padding:4px 10px; font-size:0.75rem; cursor:pointer; font-family:var(--f-head); white-space:nowrap; transition:all 0.14s; }
  .filter-tab.active { border-color:var(--neon); color:var(--neon); background:rgba(180,255,79,0.08); }
  /* 4-column snap-style grid */
  .card-grid {
    display:grid; grid-template-columns:repeat(4,1fr); gap:6px;
    padding:10px;
    flex: 1;
    min-height: 0;
    /* Vertical-only scroll: block any horizontal pan/drift on iOS */
    overflow-y: auto;
    overflow-x: hidden;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-y;
    /* Anchor inner content so it can't drift sideways */
    width: 100%;
    box-sizing: border-box;
  }
  /* Belt-and-suspenders: also prevent horizontal overflow at the screen level */
  .screen { overflow-x: hidden; }
  .card-grid-item { position:relative; aspect-ratio:63.5/88.9; cursor:pointer; }
  /* Collection card: art fills cell, name overlaid at bottom */
  .coll-card { width:100%; height:100%; border-radius:10px; overflow:hidden; position:relative;
    border:1.5px solid rgba(255,255,255,0.1);
    box-shadow:0 3px 10px rgba(0,0,0,0.6);
    transition:transform 0.18s, box-shadow 0.18s; background:#0a0a14; }
  .coll-card:hover { transform:scale(1.05); box-shadow:0 6px 20px rgba(0,0,0,0.8); z-index:5; }
  .coll-card:active { transform:scale(0.96); }
  .coll-card-art { width:100%; height:100%; object-fit:cover; display:block; }
  .coll-card-emoji { width:100%; height:100%; display:flex; align-items:center; justify-content:center;
    font-size:2.2rem; opacity:0.45; background:linear-gradient(155deg, hsl(var(--ch),22%,15%), hsl(var(--ch),16%,10%)); }
  /* Gradient overlay so name + badge read cleanly */
  .coll-card-overlay { position:absolute; inset:0; background:linear-gradient(to bottom, rgba(0,0,0,0) 38%, rgba(0,0,0,0.78) 100%); pointer-events:none; }
  .coll-card-name { position:absolute; bottom:4px; left:0; right:0; text-align:center;
    font-family:var(--f-display); font-weight:400; font-size:0.6rem; letter-spacing:0.03em; color:#fff;
    text-shadow:0 1px 4px rgba(0,0,0,0.9); padding:0 4px;
    line-height:1.05;
    white-space:normal;
    display:-webkit-box;
    -webkit-line-clamp:2;
    -webkit-box-orient:vertical;
    overflow:hidden;
    word-break:break-word;
    pointer-events:none; }
  /* Collection card badges — match gameplay: plain circles, both at top corners */
  .coll-card-energy, .coll-card-badge {
    position:absolute; top:4px; width:18px; height:18px; border-radius:50%;
    color:#fff; font-family:var(--f-mono); font-weight:700; font-size:0.72rem;
    display:flex; align-items:center; justify-content:center;
    z-index:2; pointer-events:none;
  }
  .coll-card-energy { left:4px;  background:#1d8ed4; }
  .coll-card-badge  { right:4px; background:#e74624; bottom:auto; }
  /* Selected state in collection */
  .coll-card.coll-selected { border-color:var(--neon); box-shadow:0 0 0 2px var(--neon), 0 0 18px rgba(180,255,79,0.4); }
  /* Action tray that slides up when a card is selected */
  /* Fullscreen preview when a card is clicked from the collection */
  .coll-preview-backdrop {
    position:fixed; inset:0; z-index:300;
    background:rgba(0,0,0,0.85);
    backdrop-filter:blur(6px); -webkit-backdrop-filter:blur(6px);
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    padding:20px;
    animation: backdrop-fade 0.18s ease-out;
  }
  @keyframes backdrop-fade { from{opacity:0} to{opacity:1} }
  .coll-preview-stage {
    display:flex; flex-direction:column; align-items:center; gap:18px;
    animation: preview-rise 0.24s cubic-bezier(.22,1,.36,1);
  }
  @keyframes preview-rise {
    from { transform:translateY(20px) scale(0.9); opacity:0; }
    to   { transform:translateY(0) scale(1); opacity:1; }
  }
  /* Big card — overrides default 130×182 with ~70vw width keeping 1:1.4 aspect */
  .coll-preview-card.card-view {
    width: min(320px, 70vw);
    height: auto;
    aspect-ratio: 1 / 1.4;
  }
  /* Scale badges proportionally to the bigger card so they keep the same
     visual weight as on the collection thumbnail (~22% of card width). */
  .coll-preview-card .card-energy,
  .coll-preview-card .card-power {
    width: 38px; height: 38px;
    font-size: 1.4rem;
    top: 8px;
  }
  .coll-preview-card .card-energy { left: 8px; }
  .coll-preview-card .card-power  { right: 8px; }
  /* Larger name for the bigger card */
  .coll-preview-card .card-name-text {
    font-size: 1.3rem !important;
    line-height: 1.05 !important;
  }
  .coll-preview-actions { display:flex; gap:10px; }

  .coll-tray { position:fixed; bottom:0; left:0; right:0; z-index:200;
    background:var(--bg2); border-top:1px solid var(--border);
    padding:14px 20px 24px; display:flex; gap:10px; justify-content:center; align-items:center;
    animation:tray-up 0.22s cubic-bezier(.22,1,.36,1); }
  @keyframes tray-up { from{transform:translateY(100%)} to{transform:translateY(0)} }
  .coll-tray-name { flex:1; font-size:1rem; font-weight:700; text-align:left; }
  .empty-state { color:var(--muted); font-size:0.9rem; padding:48px; text-align:center; grid-column:1/-1; }
  .collection-count { font-size:0.72rem; color:var(--muted); font-family:var(--f-mono); padding:5px 14px; background:var(--bg2); border-bottom:1px solid var(--border); }

  .editor-layout { display:flex; gap:32px; padding:24px; flex-wrap:wrap; justify-content:center; }
  .editor-form { display:flex; flex-direction:column; gap:18px; min-width:270px; max-width:380px; flex:1; }
  .editor-form label { display:flex; flex-direction:column; gap:7px; font-size:0.75rem; color:var(--muted); font-family:var(--f-mono); text-transform:uppercase; letter-spacing:0.07em; }
  .editor-form input, .editor-form select { background:var(--bg3); border:1.5px solid var(--border); color:var(--text); border-radius:9px; padding:9px 12px; font-family:var(--f-head); font-size:1rem; outline:none; transition:border-color 0.18s; }
  .editor-form input:focus, .editor-form select:focus { border-color:var(--neon); }
  .editor-form input[type="file"] { padding:6px 8px; }
  .clout-row { display:flex; gap:8px; flex-wrap:wrap; }
  .clout-btn { width:42px; height:42px; border-radius:9px; border:2px solid var(--border); background:var(--bg3); color:var(--muted); font-family:var(--f-mono); font-size:1.05rem; cursor:pointer; transition:all 0.14s; }
  .clout-btn:hover { border-color:rgba(180,255,79,0.5); color:var(--neon); }
  .clout-btn.active { border-color:var(--neon); color:var(--neon); background:rgba(180,255,79,0.1); }
  .form-err { color:#ff7878; font-size:0.82rem; }

  /* ════════════════════════════════════════════════
     CARD — full-bleed art · energy TL · power BR
     Base size 130×182 (1:1.4). Overridden per context.
     ════════════════════════════════════════════════ */
  .card-view {
    width:130px; height:182px;
    position:relative; flex-shrink:0; border-radius:12px;
    overflow:visible;          /* badges hang off corners */
    background:transparent;
    box-shadow:0 6px 20px rgba(0,0,0,0.65);
    transition:transform 0.2s cubic-bezier(.22,1,.36,1), box-shadow 0.2s;
    cursor:default;
  }
  /* ════════════════════════════════════════════
     CARD FLIP + BACK
     ════════════════════════════════════════════ */
  .card-flip {
    position:absolute; inset:0;
    transform-style:preserve-3d;
    transition: transform 0.55s cubic-bezier(.34,1.34,.5,1);
    transform: rotateY(180deg);   /* default: showing back */
    border-radius:inherit;
  }
  .card-flip.is-revealed { transform: rotateY(0deg); }
  .card-face {
    position:absolute; inset:0;
    border-radius:inherit;
    backface-visibility:hidden;
    -webkit-backface-visibility:hidden;
  }
  .card-front { transform: rotateY(0deg); }
  .card-back  { transform: rotateY(180deg); }

  /* Card back graphic — same look for every face-down card */
  .card-back-graphic {
    position:absolute; inset:0;
    border-radius:inherit;
    background:
      radial-gradient(ellipse at 50% 30%, #2d1670 0%, #120426 70%),
      linear-gradient(180deg, #1a0540 0%, #0a0218 100%);
    overflow:hidden;
    box-shadow:
      inset 0 0 0 1px hsl(280, 70%, 65%),
      inset 0 0 0 2px hsl(280, 50%, 30%),
      inset 0 0 0 3px rgba(0, 0, 0, 0.6);
  }
  .card-back-frame {
    position:absolute; inset:8%;
    border:1.5px solid rgba(180, 130, 255, 0.4);
    border-radius:6px;
    display:flex; align-items:center; justify-content:center;
    background:
      repeating-linear-gradient(45deg,
        rgba(180,130,255,0.04) 0 2px,
        transparent 2px 8px);
  }
  .card-back-logo {
    font-family:var(--f-display);
    font-size:3rem;
    color:rgba(220, 180, 255, 0.85);
    text-shadow:
      0 0 8px rgba(180, 130, 255, 0.6),
      0 2px 4px rgba(0, 0, 0, 0.8);
    line-height:1;
    z-index:2;
  }
  .card-back-glyph {
    position:absolute; top:50%; left:50%;
    transform:translate(-50%, -50%);
    font-size:5rem; color:rgba(180, 130, 255, 0.06);
    z-index:1;
  }
  /* Mini version — smaller back logo */
  .card-back-graphic.card-back-mini .card-back-logo,
  .card-back-mini .card-back-logo { font-size:1.6rem; }
  .card-back-graphic.card-back-mini .card-back-glyph,
  .card-back-mini .card-back-glyph { font-size:2.5rem; }

  /* Inner clip wraps everything that should be clipped to the rounded card shape.
     Multi-layer inset shadows paint a metallic, hue-tinted frame around the art. */
  .card-clip {
    position:absolute; inset:0;
    border-radius:inherit;
    overflow:hidden;
    background:#080810;
    box-shadow:
      inset 0 0 0 1px hsl(var(--ch), 80%, 72%),    /* bright outer highlight */
      inset 0 0 0 2px hsl(var(--ch), 55%, 42%),    /* mid metallic band */
      inset 0 0 0 3px hsl(var(--ch), 35%, 22%),    /* dark inner shadow */
      inset 0 0 0 4px rgba(0, 0, 0, 0.55);          /* deepest edge */
  }
  /* Full-bleed art layer */
  .card-art {
    position:absolute; inset:0;
    display:flex; align-items:center; justify-content:center;
    background:hsl(var(--ch),16%,8%);
  }
  .card-art img { width:100%; height:100%; object-fit:cover; display:block; }
  .card-emoji   { font-size:4rem; opacity:0.38; user-select:none; }
  /* Corner vignettes so badges always readable */
  .card-vignette {
    position:absolute; inset:0; pointer-events:none;
    background:
      radial-gradient(ellipse 60% 30% at 12% 10%, rgba(0,0,0,0.55) 0%, transparent 100%),
      radial-gradient(ellipse 60% 30% at 88% 90%, rgba(0,0,0,0.55) 0%, transparent 100%);
  }
  /* Plain solid-color circles. Energy top-LEFT (blue), Power top-RIGHT (orange).
     Circles are tight to the number — number stays the same size, just less padding. */
  .card-energy, .card-power {
    position:absolute; top:3px; z-index:5;
    width:18px; height:18px; border-radius:50%;
    color:#fff; font-family:var(--f-mono); font-weight:700; font-size:0.78rem;
    display:flex; align-items:center; justify-content:center;
    line-height:1;
  }
  .card-energy { left:3px;  background:#1d8ed4; }
  .card-power  { right:3px; background:#e74624; }
  /* Nameplate — bottom strip with stylized card name */
  .card-nameplate {
    position:absolute; bottom:0; left:0; right:0; z-index:2;
    height:30%;
    /* Lighter overlay — name still readable from the text-shadow,
       but the card art shows through more. */
    background:linear-gradient(to bottom,
      rgba(0,0,0,0) 0%,
      rgba(0,0,0,0.18) 50%,
      rgba(0,0,0,0.55) 100%);
    display:flex; align-items:flex-end; justify-content:center;
    padding:0 6px 6px;
    pointer-events:none;
  }
  .card-name-text {
    font-family:var(--f-display); font-weight:400;
    font-size:0.66rem; line-height:1.05;
    color:#fff; text-align:center;
    text-shadow:
      0 1px 0 rgba(0,0,0,0.9),
      0 0 6px rgba(0,0,0,0.85),
      0 2px 4px rgba(0,0,0,0.8);
    letter-spacing:0.02em;
    max-width:100%;
    overflow:hidden;
    display:-webkit-box;
    -webkit-line-clamp:2;
    -webkit-box-orient:vertical;
    word-break:break-word;
    padding-bottom:1px;
  }
  /* States */
  .card-view:not(.card-mini):hover { transform:translateY(-8px) scale(1.05); box-shadow:0 18px 36px rgba(0,0,0,0.75); z-index:20; }
  .card-view.card-selected { outline:2.5px solid var(--neon); box-shadow:0 0 28px rgba(180,255,79,0.5), 0 14px 32px rgba(0,0,0,0.8) !important; z-index:20; }
  .card-view.card-playing  { animation:card-launch 0.46s cubic-bezier(.36,.07,.19,.97); }
  @keyframes card-launch {
    0%  { transform:translateY(0) scale(1); }
    28% { transform:translateY(-44px) rotate(-10deg) scale(1.12); }
    60% { transform:translateY(12px)  rotate(4deg)  scale(0.94); }
    80% { transform:translateY(-5px)  rotate(-1deg) scale(1.02); }
    100%{ transform:translateY(0) scale(1); }
  }
  .card-land { animation:land 0.36s cubic-bezier(.22,1,.36,1); }
  @keyframes land {
    from { transform:translateY(-36px) scale(1.1); opacity:0; }
    to   { transform:translateY(0)     scale(1);   opacity:1; }
  }
  /* Wrapper for zone cards (allows positioning the ✕ button outside the card) */
  .zone-card-wrap { position:relative; width:100%; max-width:64px; line-height:0; justify-self:center; }
  /* The bright X button on uncommitted cards — direct unplay */
  .card-unplay-btn {
    position:absolute; top:-7px; right:-7px; z-index:6;
    width:22px; height:22px; border-radius:50%;
    background:linear-gradient(135deg,#ff5050,#c40020);
    color:#fff; border:1.5px solid #fff;
    font-family:var(--f-head); font-weight:700; font-size:0.72rem;
    display:flex; align-items:center; justify-content:center;
    cursor:pointer; padding:0; line-height:1;
    box-shadow:0 2px 8px rgba(0,0,0,0.7);
    pointer-events:auto;
    touch-action:manipulation;
    transition:transform 0.12s, filter 0.12s;
    animation:unplay-pulse 1.2s ease-in-out infinite;
  }
  .card-unplay-btn:hover  { filter:brightness(1.15); }
  .card-unplay-btn:active { transform:scale(0.85); }
  @keyframes unplay-pulse {
    0%,100% { box-shadow:0 2px 8px rgba(0,0,0,0.7), 0 0 0 0 rgba(255,80,80,0.7); }
    50%      { box-shadow:0 2px 8px rgba(0,0,0,0.7), 0 0 0 6px rgba(255,80,80,0); }
  }
  /* ════════════════════════════════════════════
     REVEAL EFFECT ART — burst ring, glow, floating label
     ════════════════════════════════════════════ */
  /* Wrapper around each card in a zone slot — provides positioning context
     for the reveal-effect burst/label which are absolute children. */
  .zone-slot-cell {
    position:relative;
    width:100%;
    max-width:64px;
    justify-self:center;
    line-height:0;
  }

  /* Burst ring expands outward and fades */
  /* ════════════════════════════════════════════
     POWER DELTA LABEL — floating +N / -N when a card's power changes
     ════════════════════════════════════════════ */
  @keyframes power-delta-rise {
    0%   { opacity:0; transform:translate(-50%, 0%) scale(0.6); }
    20%  { opacity:1; transform:translate(-50%, -40%) scale(1.25); }
    65%  { opacity:1; transform:translate(-50%, -85%) scale(1.05); }
    100% { opacity:0; transform:translate(-50%, -130%) scale(1); }
  }
  .power-delta-label {
    position:absolute; left:50%; top:50%; z-index:35;
    font-family:var(--f-display); font-size:1.6rem;
    font-weight:400; letter-spacing:0.02em;
    pointer-events:none; line-height:1;
    animation: power-delta-rise 1.0s cubic-bezier(.22,.61,.36,1) forwards;
  }

  /* ════════════════════════════════════════════
     MOVE EFFECT — fires when a Snap ability moves a card between zones.
     ════════════════════════════════════════════ */
  .move-fx-layer { position:fixed; inset:0; z-index:80; pointer-events:none; }
  .move-flash {
    position:fixed;
    border-radius:14px;
    pointer-events:none;
    animation: move-flash-pulse 1.0s ease-out forwards;
  }
  .move-flash-src {
    border:3px solid #ff5e8a;
    box-shadow: 0 0 28px rgba(255,94,138,0.55), inset 0 0 28px rgba(255,94,138,0.4);
  }
  .move-flash-dst {
    border:3px solid #5fd4ff;
    box-shadow: 0 0 28px rgba(95,212,255,0.6), inset 0 0 28px rgba(95,212,255,0.45);
  }
  @keyframes move-flash-pulse {
    0%   { opacity:0; transform:scale(0.95); }
    20%  { opacity:1; transform:scale(1); }
    80%  { opacity:1; }
    100% { opacity:0; transform:scale(1.02); }
  }
  .move-arrow-svg {
    position:fixed; inset:0; width:100%; height:100%;
    pointer-events:none;
    animation: move-arrow-fade 1.0s ease-out forwards;
  }
  @keyframes move-arrow-fade {
    0%   { opacity:0; }
    25%  { opacity:1; }
    80%  { opacity:1; }
    100% { opacity:0; }
  }
  .move-label {
    position:fixed; z-index:90;
    width:80px; text-align:center;
    font-family:var(--f-display); font-size:0.95rem;
    color:#5fd4ff;
    text-shadow: 0 0 10px rgba(95,212,255,0.85), 0 2px 4px rgba(0,0,0,0.95);
    letter-spacing:0.08em;
    pointer-events:none;
    animation: move-label-rise 1.0s ease-out forwards;
  }
  @keyframes move-label-rise {
    0%   { opacity:0; transform:translateY(0) scale(0.8); }
    25%  { opacity:1; transform:translateY(-8px) scale(1.1); }
    75%  { opacity:1; transform:translateY(-18px) scale(1); }
    100% { opacity:0; transform:translateY(-28px) scale(0.95); }
  }

  @keyframes reveal-burst-ring {
    0%   { transform: scale(0.85); opacity: 0; }
    20%  { opacity: 1; }
    100% { transform: scale(1.9); opacity: 0; }
  }
  .reveal-burst {
    position:absolute; inset:-3px; z-index:25;
    border-radius:9px;
    border:2.5px solid #fff;
    pointer-events:none;
    animation: reveal-burst-ring 0.78s cubic-bezier(.22,.61,.36,1) forwards;
  }
  /* Inner radial flash */
  @keyframes reveal-burst-flash {
    0%   { opacity: 0; transform: scale(0.5); }
    25%  { opacity: 0.95; transform: scale(1); }
    100% { opacity: 0; transform: scale(1.4); }
  }
  .reveal-burst-inner {
    position:absolute; inset:0; z-index:24;
    border-radius:8px;
    pointer-events:none;
    animation: reveal-burst-flash 0.78s ease-out forwards;
  }
  /* Floating label — ability name, rises and fades */
  @keyframes reveal-label-float {
    0%   { transform: translate(-50%, 0%) scale(0.6); opacity: 0; }
    20%  { transform: translate(-50%, -45%) scale(1.15); opacity: 1; }
    65%  { transform: translate(-50%, -90%) scale(1.0); opacity: 1; }
    100% { transform: translate(-50%, -130%) scale(0.95); opacity: 0; }
  }
  .reveal-label {
    position:absolute; left:50%; bottom:100%; z-index:30;
    font-family:var(--f-display); font-size:0.95rem;
    letter-spacing:0.05em; white-space:nowrap;
    pointer-events:none; line-height:1;
    animation: reveal-label-float 1.0s cubic-bezier(.22,.61,.36,1) forwards;
  }

  /* Card "lands" when placed into a zone — brief pop + glow */
  @keyframes card-land-pop {
    0%   { transform: scale(0.7) rotate(-8deg); opacity: 0; }
    45%  { transform: scale(1.12) rotate(2deg); opacity: 1; }
    70%  { transform: scale(0.96) rotate(-1deg); }
    100% { transform: scale(1) rotate(0deg); }
  }
  .card-view.card-land {
    animation: card-land-pop 0.42s cubic-bezier(.34,1.56,.64,1) both;
  }
  /* Uncommitted player card (placed this turn) — draggable to move/unplay */
  .card-view.card-uncommitted {
    cursor:grab;
    touch-action:none;             /* required for mobile drag */
    -webkit-touch-callout:none;
    -webkit-user-select:none;
    box-shadow:0 0 0 1.5px rgba(180,255,79,0.6), 0 4px 14px rgba(180,255,79,0.2);
    animation:uncommitted-pulse 1.8s ease-in-out infinite;
  }
  .card-view.card-uncommitted:active { cursor:grabbing; }
  @keyframes uncommitted-pulse {
    0%,100% { box-shadow:0 0 0 1.5px rgba(180,255,79,0.5), 0 4px 12px rgba(180,255,79,0.15); }
    50%      { box-shadow:0 0 0 2px rgba(180,255,79,0.9),  0 4px 18px rgba(180,255,79,0.35); }
  }
  /* ── Mini (zones): fills 1/2 of zone width, height by aspect-ratio ── */
  .card-mini {
    width:100%;
    aspect-ratio: 1 / 1.4;     /* Marvel Snap card proportion */
    height:auto;
    border-radius:7px;
    max-width:64px;            /* hard cap so they never get huge on tablets */
  }
  .card-mini .card-energy { width:14px; height:14px; font-size:0.58rem; top:2px; left:2px; }
  .card-mini .card-power  { width:14px; height:14px; font-size:0.58rem; top:2px; right:2px; bottom:auto; left:auto; }
  .card-mini .card-emoji  { font-size:2rem; }
  .card-mini:hover { transform:translateY(-3px) scale(1.06)!important; box-shadow:0 8px 18px rgba(0,0,0,0.7)!important; }
  .card-mini[onclick], .card-mini { /* clickable mini cards in zones use cursor:pointer when onClick is set */ }

  /* ════════════════════════════════════════════
     GAME SCREEN
     ════════════════════════════════════════════ */
  .game-screen {
    background: radial-gradient(ellipse at 50% 25%, #0d1e38 0%, #05050f 70%);
    display: flex; flex-direction: column;
    height: 100vh; max-height: 100vh; overflow: hidden;
    touch-action: none; /* let JS handle all pointer events */
    user-select: none;
    /* iPhone safe areas — notch + home indicator */
    padding-top: env(safe-area-inset-top);
    padding-bottom: env(safe-area-inset-bottom);
  }

  /* ── Top bar ── */
  .debug-status { position:absolute; top:2px; left:50%; transform:translateX(-50%); z-index:1000;
    background:rgba(255,255,255,0.92); color:#000; font-family:var(--f-mono); font-size:0.66rem; font-weight:700;
    padding:3px 12px; border-radius:10px; pointer-events:none; max-width:90vw;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    transition:background 0.12s; }
  .debug-status.debug-hit { background:rgba(180,255,79,0.95); box-shadow:0 0 16px rgba(180,255,79,0.6); }
  .game-top { display:flex; align-items:center; justify-content:space-between; padding:8px 12px; flex-shrink:0; height:56px; }
  .player-pill {
    display:flex; align-items:center; gap:8px;
    padding:3px 8px; border-radius:20px;
    border:1.5px solid transparent;
    transition: border-color 0.3s, box-shadow 0.3s, background 0.3s;
  }
  /* Glowing gold border + soft halo on whichever side has priority — */
  /* matches Marvel Snap's glowing name plate around the priority player. */
  .player-pill.has-priority {
    border-color: #ffd84d;
    background: rgba(255, 216, 77, 0.08);
    box-shadow: 0 0 14px rgba(255, 216, 77, 0.45), 0 0 28px rgba(255, 200, 30, 0.2);
    animation: priority-pulse 2.2s ease-in-out infinite;
  }
  @keyframes priority-pulse {
    0%,100% { box-shadow: 0 0 12px rgba(255, 216, 77, 0.4), 0 0 22px rgba(255, 200, 30, 0.18); }
    50%      { box-shadow: 0 0 20px rgba(255, 216, 77, 0.7), 0 0 38px rgba(255, 200, 30, 0.35); }
  }
  .player-pill.has-priority .player-name { color: #ffe9a0; text-shadow: 0 0 8px rgba(255, 200, 50, 0.6); }
  .player-name-block { display:flex; flex-direction:column; gap:1px; }
  .hand-count { font-family:var(--f-mono); font-size:0.6rem; color:rgba(255,255,255,0.55); letter-spacing:0.04em; }
  .player-avatar { width:38px; height:38px; border-radius:50%; background:var(--bg3); border:2px solid rgba(255,255,255,0.15); display:flex; align-items:center; justify-content:center; font-size:1.2rem; }
  .player-name { font-size:0.78rem; font-weight:700; color:var(--text); letter-spacing:0.04em; }
  .energy-crystal { display:flex; flex-direction:column; align-items:center; gap:2px; }
  .crystal-gem { width:38px; height:38px; background:linear-gradient(135deg,#7040f0,#a070ff); border-radius:6px; transform:rotate(45deg); display:flex; align-items:center; justify-content:center; box-shadow:0 0 20px rgba(130,80,255,0.6); }
  .crystal-gem span { transform:rotate(-45deg); font-family:var(--f-mono); font-weight:700; font-size:1.05rem; color:#fff; }
  .crystal-label { font-size:0.55rem; color:var(--muted); font-family:var(--f-mono); letter-spacing:0.06em; }

  /* ── Zones ── */
  .zones-row { display:flex; gap:6px; padding:4px 8px; flex:1; min-height:0; align-items:stretch; }
  .zone {
    flex:1; display:flex; flex-direction:column;
    border-radius:14px; overflow:hidden;
    border:1.5px solid rgba(255,255,255,0.07);
    background:
      /* horizon glow */
      radial-gradient(ellipse 120% 35% at 50% 50%, var(--zone-accent,transparent) 0%, transparent 70%),
      /* sky → horizon → ground */
      linear-gradient(180deg,
        var(--zone-sky,#0d1020)     0%,
        var(--zone-horizon,#16244a) 50%,
        var(--zone-ground,#040408) 100%
      );
    background-size: cover;
    background-position: center;
    transition:border-color 0.18s, box-shadow 0.18s;
    position:relative;
  }
  /* Image-backed zone (custom location art) */
  .zone.has-bg-image { background-size:cover; background-position:center; }
  .zone.has-bg-image::before {
    content:""; position:absolute; inset:0;
    background:linear-gradient(180deg, rgba(0,0,0,0.18) 0%, rgba(0,0,0,0.05) 50%, rgba(0,0,0,0.45) 100%);
    pointer-events:none;
  }

  /* Drag-over highlight (valid drop) */
  .zone.drag-over {
    border-color:var(--neon);
    box-shadow:0 0 0 2px var(--neon), 0 0 30px rgba(180,255,79,0.45);
  }
  /* Drag-over but blocked (full zone) — red, can't drop */
  .zone.drag-blocked {
    border-color:#ff4040;
    box-shadow:0 0 0 2px #ff4040, 0 0 30px rgba(255,64,64,0.4);
  }
  .zone-slot {
    flex:1; min-height:0;
    display:grid;
    grid-template-columns:1fr 1fr;     /* exactly 2 columns, Snap-style 2x2 */
    grid-auto-rows:min-content;
    gap:4px; padding:5px;
    place-items:start center;
    overflow:hidden;
  }
  /* AI cards fill from BOTTOM-LEFT of AI slot (closest to center bar) */
  .zone-slot.ai-slot     { border-bottom:1px solid rgba(255,255,255,0.05); align-content:end; }
  /* Player cards fill from TOP-LEFT of player slot (closest to center bar) */
  .zone-slot.player-slot { align-content:start; }
  .zone-slot .zone-empty { grid-column:1 / -1; align-self:center; justify-self:center; }
  .zone-empty { color:rgba(255,255,255,0.07); font-size:0.9rem; align-self:center; }
  .zone-bar {
    flex-shrink:0;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    gap:5px; padding:7px 6px;
    border-top:1px solid rgba(255,255,255,0.07);
    border-bottom:1px solid rgba(255,255,255,0.07);
    background:rgba(0,0,0,0.4);
    transition:background 0.3s;
  }
  .zone-bar.winning-player { background:rgba(180,255,79,0.1); }
  .zone-bar.winning-ai     { background:rgba(255,95,186,0.1); }
  /* Hexagon-style score badge — animates when value changes */
  .zone-score-hex {
    width:24px; height:24px; border-radius:5px;
    display:flex; align-items:center; justify-content:center;
    font-family:var(--f-mono); font-weight:700; font-size:0.78rem;
    background:rgba(255,255,255,0.08);
    transition: background 0.3s, transform 0.3s, color 0.3s;
  }
  .zone-score-hex.leading-player { background:rgba(180,255,79,0.3); color:var(--neon); transform:scale(1.08); box-shadow:0 0 12px rgba(180,255,79,0.4); }
  .zone-score-hex.leading-ai     { background:rgba(255,95,186,0.3); color:var(--hot); transform:scale(1.08); box-shadow:0 0 12px rgba(255,95,186,0.4); }
  /* Pulse animation when score increases this turn */
  @keyframes score-pulse {
    0%   { transform: scale(1); }
    40%  { transform: scale(1.4); filter: brightness(1.5); }
    100% { transform: scale(1.08); filter: brightness(1); }
  }
  .zone-score-hex.score-changed { animation: score-pulse 0.5s cubic-bezier(.34,1.56,.64,1) both; }
  .zone-name    { font-family:var(--f-display); font-size:0.78rem; font-weight:400; letter-spacing:0.04em; color:#fff; text-align:center; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; width:100%; }
  .zone-ability { font-size:0.48rem; color:rgba(255,255,255,0.45); text-align:center; line-height:1.35; width:100%; }

  /* ── Bottom bar ── */
  .game-bottom {
    display:flex; align-items:center; justify-content:space-between;
    padding:6px 14px; flex-shrink:0; height:56px;
    background:rgba(0,0,0,0.5); border-top:1px solid rgba(255,255,255,0.06);
  }
  .retreat-btn {
    background:rgba(180,40,40,0.25); border:1.5px solid rgba(220,60,60,0.45);
    color:#ff9090; border-radius:22px; padding:8px 18px;
    font-family:var(--f-display); font-size:0.95rem; font-weight:400;
    letter-spacing:0.08em; cursor:pointer;
    transition:background 0.15s;
    box-shadow:0 2px 8px rgba(180,40,40,0.18);
  }
  .retreat-btn:active { background:rgba(200,40,40,0.4); }
  .end-turn-btn {
    background:linear-gradient(135deg,#4a9eff,#1a6fd4);
    color:#fff; border:none; border-radius:22px; padding:8px 18px;
    font-family:var(--f-display); font-size:0.95rem; font-weight:400;
    letter-spacing:0.08em; cursor:pointer;
    box-shadow:0 0 18px rgba(74,158,255,0.4); transition:filter 0.15s,transform 0.1s;
  }
  .end-turn-btn.reveal-mode { background:linear-gradient(135deg,#b4ff4f,#78c800); color:#050508; box-shadow:0 0 18px rgba(180,255,79,0.4); }
  .end-turn-btn.ready { background:linear-gradient(135deg,#b4ff4f,#78c800); color:#050508; box-shadow:0 0 22px rgba(180,255,79,0.5); animation:end-turn-pulse 1.4s ease-in-out infinite; }

  /* ════════════════════════════════════════════
     CARD TILT + PARALLAX SHINE
     ════════════════════════════════════════════ */
  /* Smooth reset when pointer leaves; live transform during move */
  .card-tiltable {
    transform-style:preserve-3d;
    transition:transform 0.42s cubic-bezier(.22,1,.36,1), box-shadow 0.25s;
    will-change:transform;
    --shine-x:50%;
    --shine-y:50%;
  }
  /* While actively tilting, shorter transition for responsiveness */
  .card-tiltable:hover { transition:transform 60ms linear, box-shadow 0.25s; }

  /* Shine overlay that follows the pointer position via CSS variables */
  .popup-shine, .coll-shine {
    position:absolute; inset:0; z-index:4; pointer-events:none;
    border-radius:inherit;
    background:radial-gradient(circle at var(--shine-x,50%) var(--shine-y,50%),
      rgba(255,255,255,0.32) 0%,
      rgba(255,255,255,0.08) 18%,
      rgba(255,255,255,0) 45%);
    opacity:0;
    transition:opacity 0.18s;
    mix-blend-mode:screen;
  }
  .card-tiltable:hover .popup-shine,
  .card-tiltable:hover .coll-shine { opacity:1; }

  /* Slightly stronger drop-shadow when tilted (premium card-as-object feel) */
  .card-tiltable:hover {
    box-shadow:
      0 24px 40px rgba(0,0,0,0.7),
      0 0 32px hsl(var(--ch),60%,40%,0.28);
  }
  @keyframes end-turn-pulse {
    0%,100% { box-shadow:0 0 22px rgba(180,255,79,0.5); }
    50%      { box-shadow:0 0 38px rgba(180,255,79,0.85); }
  }
  .end-turn-btn:active { transform:scale(0.93); }
  .end-turn-btn:disabled { opacity:0.28; }
  .turn-counter { font-size:0.55rem; opacity:0.7; font-family:var(--f-mono); text-align:center; margin-top:1px; }
  .status-hint { font-size:0.7rem; color:rgba(255,255,255,0.6); font-family:var(--f-display); letter-spacing:0.06em; text-align:center; }

  /* ── Hand ── */
  .hand-area {
    position:relative; flex-shrink:0; height:140px;
    background:rgba(0,0,0,0.65);
    display:flex; align-items:flex-end; justify-content:center;
    padding-bottom:8px; overflow:visible;
    touch-action:none;
  }
  .hand-cards { display:flex; align-items:flex-end; gap:3px; position:relative; }
  /* Each slot's width ≈ card width (no overlap). Cards are wider on smaller hand. */
  .hand-slot {
    position:relative; flex-shrink:0;
    width:var(--slot-w,82px); height:122px;
  }
  .hand-slot .card-view {
    position:relative;             /* normal flow, not absolute */
    width:100%; height:100%;
    border-radius:10px;
    transform-origin:bottom center;
    transition:transform 0.2s cubic-bezier(.22,1,.36,1), box-shadow 0.2s, opacity 0.15s;
    cursor:grab;
    touch-action:none;
    -webkit-user-select:none;
    -webkit-touch-callout:none;
  }
  .hand-slot .card-view:active { cursor:grabbing; }
  .hand-slot .card-view .card-emoji  { font-size:2.6rem; }
  .hand-slot .card-view .card-energy { width:16px; height:16px; font-size:0.66rem; top:3px; left:3px; }
  .hand-slot .card-view .card-power  { width:16px; height:16px; font-size:0.66rem; top:3px; right:3px; bottom:auto; left:auto; }
  .hand-slot .card-view .card-nameplate { height:36%; padding:0 4px 6px; align-items:flex-end; }
  .hand-slot .card-view .card-name-text {
    font-size:0.5rem;
    letter-spacing:0.02em;
    line-height:1.05;
    white-space:normal;          /* allow wrapping for long names */
    overflow:hidden;
    text-overflow:clip;
    display:-webkit-box;
    -webkit-line-clamp:2;        /* max 2 lines */
    -webkit-box-orient:vertical;
    word-break:break-word;
  }
  /* Pop up when selected */
  .hand-slot .card-view.card-selected { transform:translateY(-22px) scale(1.08) !important; box-shadow:0 0 0 2px var(--neon), 0 0 20px rgba(180,255,79,0.45), 0 14px 28px rgba(0,0,0,0.8) !important; z-index:60 !important; }
  /* Dragging ghost */
  .drag-ghost {
    position:fixed; pointer-events:none; z-index:999;
    width:76px; height:107px; border-radius:9px; overflow:hidden;
    opacity:0.88; transform:translate(-50%,-50%) scale(1.12) rotate(-4deg);
    box-shadow:0 16px 40px rgba(0,0,0,0.85);
  }

  /* ── Card popup ── */
  /* Backdrop is purely visual — pointer-events disabled so it can never block
     card drags or zone hit-testing. Popup is dismissed by tapping the card
     again, tapping another card, starting a drag, or the X button. */
  .card-popup-backdrop { position:fixed; inset:0; z-index:200; background:transparent; pointer-events:none; }
  .card-popup {
    position:fixed; bottom:160px; left:50%; transform:translateX(-50%);
    z-index:201;
    /* Marvel-Snap-card proportions: portrait 1:1.4 — width sized so height ≈ 308px */
    width:220px; aspect-ratio:1 / 1.4;
    border-radius:14px;
    /* Outer glow + metallic frame via inset shadows tinted by card hue */
    box-shadow:
      0 20px 50px rgba(0,0,0,0.9),
      0 0 30px hsl(var(--ch),60%,40%,.3),
      inset 0 0 0 1px hsl(var(--ch),80%,72%),
      inset 0 0 0 2px hsl(var(--ch),55%,42%),
      inset 0 0 0 3px hsl(var(--ch),35%,22%),
      inset 0 0 0 4px rgba(0,0,0,0.55);
    background:#080810;
    overflow:visible;
    animation:popup-rise 0.2s cubic-bezier(.22,1,.36,1);
    pointer-events:none;
  }
  @keyframes popup-rise { from{transform:translateX(-50%) translateY(16px);opacity:0} to{transform:translateX(-50%) translateY(0);opacity:1} }
  .popup-art {
    position:absolute; top:0; left:0; right:0; bottom:0;
    overflow:hidden; border-radius:13px;
  }
  .popup-close {
    /* Floats just OUTSIDE the popup top-right corner so it never overlaps badges. */
    position:absolute; top:-12px; right:-12px; z-index:6;
    width:30px; height:30px; border-radius:50%;
    background:#1a1a26; color:#fff; border:2px solid rgba(255,255,255,0.5);
    font-family:var(--f-head); font-weight:700; font-size:0.85rem;
    display:flex; align-items:center; justify-content:center;
    cursor:pointer; pointer-events:auto;
    box-shadow:0 4px 10px rgba(0,0,0,0.85);
    transition:background 0.15s, transform 0.1s;
  }
  .popup-close:hover  { background:rgba(255,80,80,0.8); }
  .popup-close:active { transform:scale(0.9); }
  .popup-art img { width:100%; height:100%; object-fit:cover; }
  .popup-art-emoji { width:100%; height:100%; display:flex; align-items:center; justify-content:center; font-size:4rem; opacity:0.45; background:hsl(var(--ch),18%,7%); }
  .popup-badge {
    position:absolute; z-index:4;
    width:24px; height:24px; border-radius:50%;
    font-family:var(--f-mono); font-weight:700; font-size:0.95rem;
    display:flex; align-items:center; justify-content:center;
    box-shadow:0 3px 8px rgba(0,0,0,0.9);
  }
  .popup-badge.energy-badge { top:8px; left:8px; background:#1d8ed4; color:#fff; }
  .popup-badge.power-badge  { top:8px; right:8px; background:#e74624; color:#fff; }
  .popup-body {
    position:absolute; left:0; right:0; bottom:0; z-index:3;
    padding:60px 12px 14px;
    display:flex; flex-direction:column; gap:4px;
    border-radius:0 0 13px 13px;
    /* Lighter overlay so card art shows through behind the name */
    background:linear-gradient(to bottom,
      rgba(0,0,0,0)   0%,
      rgba(0,0,0,0.35) 50%,
      rgba(0,0,0,0.7) 100%);
    pointer-events:none;
  }
  .popup-name {
    font-family:var(--f-display); font-size:1.45rem; font-weight:400;
    letter-spacing:0.02em; color:#fff; flex:1; line-height:1.04;
    text-shadow:
      0 1px 0 rgba(0,0,0,0.95),
      0 0 8px rgba(0,0,0,0.85),
      0 2px 6px rgba(0,0,0,0.8);
    white-space:normal; word-break:break-word;
    display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;
  }
  .popup-name-row { display:flex; align-items:center; gap:8px; }
  .popup-info-btn {
    pointer-events:auto;
    width:24px; height:24px; border-radius:50%; border:1.5px solid rgba(255,255,255,0.25);
    background:rgba(255,255,255,0.05); color:rgba(255,255,255,0.65);
    font-family:Georgia, serif; font-style:italic; font-weight:700; font-size:0.85rem;
    display:flex; align-items:center; justify-content:center;
    cursor:pointer; transition:all 0.15s; flex-shrink:0; padding:0; line-height:1;
  }
  .popup-info-btn:hover { background:rgba(255,255,255,0.12); color:#fff; }
  .popup-info-btn.active { background:hsl(var(--ch),60%,40%); border-color:hsl(var(--ch),70%,55%); color:#fff; }
  .popup-ability {
    font-size:0.74rem; color:#fff; line-height:1.35;
    text-shadow:0 1px 4px rgba(0,0,0,0.9);
  }
  .popup-snap-credit {
    color: rgba(255, 220, 100, 0.82);
    font-style: italic;
    font-size: 0.66rem;
    text-shadow: 0 1px 3px rgba(0,0,0,0.85);
  }
  .popup-flavor {
    font-size:0.7rem; color:rgba(255,255,255,0.78); font-style:italic; line-height:1.35;
    border-top:1px solid rgba(255,255,255,0.15); padding-top:5px;
    text-shadow:0 1px 3px rgba(0,0,0,0.9);
  }
  .popup-hint    { font-size:0.62rem; color:rgba(180,255,79,0.7); font-family:var(--f-mono); text-align:center; }
  .popup-action-btn {
    pointer-events:auto;
    background:linear-gradient(135deg,#ff8c5a,#d44a2c); color:#fff; border:none;
    border-radius:10px; padding:8px 14px; font-family:var(--f-head);
    font-weight:700; font-size:0.78rem; letter-spacing:0.05em;
    cursor:pointer; box-shadow:0 0 14px rgba(255,140,90,0.4);
    transition:filter 0.15s, transform 0.1s;
    align-self:center; margin-top:4px;
  }
  .popup-action-btn:hover  { filter:brightness(1.1); }
  .popup-action-btn:active { transform:scale(0.95); }

  /* Result overlay */
  .result-overlay { position:absolute; inset:0; z-index:300; display:flex; align-items:center; justify-content:center; background:rgba(0,0,0,0.7); backdrop-filter:blur(8px); animation:fade-in 0.3s; }
  @keyframes fade-in { from{opacity:0} to{opacity:1} }
  .result-card { background:var(--bg2); border:1.5px solid var(--border); border-radius:20px; padding:36px 40px; text-align:center; display:flex; flex-direction:column; gap:16px; }
  .result-title { font-size:2rem; font-weight:700; }
  .result-sub { font-size:0.85rem; color:var(--muted); }
  .result-actions { display:flex; gap:10px; justify-content:center; }

  /* Card detail popup */

  @keyframes pop { from{transform:scaleY(0);opacity:0} to{transform:scaleY(1);opacity:1} }


  /* ════════════════════════════════════════════
     DECK INFO BUTTONS (Snap-style pill buttons)
     ════════════════════════════════════════════ */
  .deck-info-row {
    display:flex; gap:5px; align-items:center; justify-content:center;
    padding:3px 8px 0;
    flex-shrink:0;
  }
  .deck-pill {
    display:flex; align-items:center; gap:4px;
    background:rgba(255,255,255,0.07); border:1px solid rgba(255,255,255,0.12);
    border-radius:20px; padding:4px 10px;
    font-family:var(--f-mono); font-size:0.62rem; font-weight:700;
    color:rgba(255,255,255,0.65); cursor:pointer;
    transition:background 0.14s, border-color 0.14s, color 0.14s;
    letter-spacing:0.04em;
    touch-action:manipulation;
    user-select:none;
  }
  .deck-pill:active { transform:scale(0.92); }
  .deck-pill.deck-pill-deck    { border-color:rgba(95,212,255,0.4); }
  .deck-pill.deck-pill-discard { border-color:rgba(255,160,60,0.4); }
  .deck-pill.deck-pill-destroy { border-color:rgba(255,90,90,0.4);  }
  .deck-pill:hover              { background:rgba(255,255,255,0.13); color:#fff; }
  .deck-pill .pill-icon { font-size:0.75rem; line-height:1; }
  .deck-pill .pill-count {
    background:rgba(255,255,255,0.15); border-radius:10px;
    padding:1px 5px; font-size:0.58rem;
  }
  .deck-pill.deck-pill-deck    .pill-count { background:rgba(95,212,255,0.25);  color:#5fd4ff; }
  .deck-pill.deck-pill-discard .pill-count { background:rgba(255,160,60,0.25);  color:#ffa03c; }
  .deck-pill.deck-pill-destroy .pill-count { background:rgba(255,90,90,0.25);   color:#ff7070; }

  /* ── Deck panel drawer (slides up from bottom like Snap) ── */
  .deck-panel-backdrop {
    position:fixed; inset:0; z-index:200;
    background:rgba(0,0,0,0.6); backdrop-filter:blur(4px);
    display:flex; align-items:flex-end;
    animation:backdrop-in 0.18s ease-out;
  }
  @keyframes backdrop-in { from{opacity:0} to{opacity:1} }
  .deck-panel {
    width:100%; max-height:72vh;
    background:var(--bg2); border-top:1px solid rgba(255,255,255,0.1);
    border-radius:18px 18px 0 0;
    display:flex; flex-direction:column;
    animation:panel-slide-up 0.26s cubic-bezier(.22,1,.36,1);
    overflow:hidden;
  }
  @keyframes panel-slide-up { from{transform:translateY(100%)} to{transform:translateY(0)} }
  .deck-panel-header {
    display:flex; align-items:center; justify-content:space-between;
    padding:14px 18px 10px; flex-shrink:0;
    border-bottom:1px solid rgba(255,255,255,0.07);
  }
  .deck-panel-title {
    font-family:var(--f-display); font-size:1.1rem; font-weight:400;
    letter-spacing:0.06em; color:#fff;
  }
  .deck-panel-count {
    font-family:var(--f-mono); font-size:0.7rem; color:var(--muted);
  }
  .deck-panel-close {
    background:rgba(255,255,255,0.08); border:none; border-radius:50%;
    width:28px; height:28px; color:var(--muted); font-size:1rem;
    display:flex; align-items:center; justify-content:center;
    cursor:pointer; transition:background 0.12s;
  }
  .deck-panel-close:active { background:rgba(255,255,255,0.18); }
  .deck-panel-grid {
    display:grid; grid-template-columns:repeat(4,1fr);
    gap:8px; padding:12px;
    overflow-y:auto; -webkit-overflow-scrolling:touch;
    flex:1; min-height:0;
  }
  .deck-panel-empty {
    grid-column:1/-1; text-align:center;
    color:var(--muted); font-size:0.85rem; padding:32px;
  }
  .deck-panel-card-wrap {
    position:relative; aspect-ratio:1/1.4; cursor:pointer;
  }

  /* ════════════════════════════════════════════
     SHUFFLE / DEAL ANIMATION (game-start)
     ════════════════════════════════════════════ */
  .shuffle-overlay {
    position:absolute; inset:0; z-index:400;
    display:flex; flex-direction:column;
    align-items:center; justify-content:center;
    background:radial-gradient(ellipse at 50% 55%, #16082e 0%, #05050f 70%);
    gap:24px;
    pointer-events:none;
  }
  .shuffle-title {
    font-family:var(--f-display); font-size:1.8rem; color:var(--neon);
    letter-spacing:0.12em; opacity:0;
    animation: shuffle-title-in 0.5s 0.1s ease-out forwards;
  }
  @keyframes shuffle-title-in {
    from { opacity:0; transform:translateY(-12px); }
    to   { opacity:1; transform:translateY(0); }
  }
  .shuffle-deck-area {
    position:relative; width:120px; height:168px;
  }
  .shuffle-card {
    position:absolute; inset:0; border-radius:12px;
    background:radial-gradient(ellipse at 50% 30%, #2d1670 0%, #120426 70%);
    box-shadow:inset 0 0 0 1px hsl(280,70%,65%), 0 8px 24px rgba(0,0,0,0.7);
    display:flex; align-items:center; justify-content:center;
    font-family:var(--f-display); font-size:2.2rem; color:rgba(220,180,255,0.7);
  }
  /* Each stacked card fans slightly then collapses */
  .shuffle-card-1 { transform:rotate(-6deg) translateX(-28px); }
  .shuffle-card-2 { transform:rotate(-3deg) translateX(-14px); }
  .shuffle-card-3 { transform:rotate(0deg); }
  .shuffle-card-4 { transform:rotate(3deg) translateX(14px); }
  .shuffle-card-5 { transform:rotate(6deg) translateX(28px); }
  .shuffle-anim .shuffle-card-1 { animation:deal-card 0.35s 0.3s  cubic-bezier(.34,1.56,.64,1) both; }
  .shuffle-anim .shuffle-card-2 { animation:deal-card 0.35s 0.5s  cubic-bezier(.34,1.56,.64,1) both; }
  .shuffle-anim .shuffle-card-3 { animation:deal-card 0.35s 0.7s  cubic-bezier(.34,1.56,.64,1) both; }
  .shuffle-anim .shuffle-card-4 { animation:deal-card 0.35s 0.9s  cubic-bezier(.34,1.56,.64,1) both; }
  .shuffle-card-fan { animation:fan-in 0.6s 0.05s cubic-bezier(.22,1,.36,1) both; }
  @keyframes fan-in {
    from { transform:scale(0.7) translateY(40px); opacity:0; }
    to   { transform:scale(1) translateY(0); opacity:1; }
  }
  @keyframes deal-card {
    0%   { transform:translate(0,0) rotate(0deg) scale(1); opacity:1; }
    60%  { transform:translate(0, -90px) scale(1.15); opacity:1; }
    100% { transform:translate(0, 220px) scale(0.85); opacity:0; }
  }
  .shuffle-sub {
    font-size:0.75rem; color:var(--muted); font-family:var(--f-mono);
    letter-spacing:0.1em; opacity:0;
    animation:shuffle-title-in 0.4s 0.4s ease-out forwards;
  }
  .shuffle-count {
    font-family:var(--f-mono); font-size:0.7rem; color:rgba(95,212,255,0.8);
    opacity:0; animation:shuffle-title-in 0.4s 0.6s ease-out forwards;
  }
  ::-webkit-scrollbar { width:5px; }
  ::-webkit-scrollbar-track { background:var(--bg); }
  ::-webkit-scrollbar-thumb { background:var(--bg3); border-radius:3px; }
`;

// ─── Components ───────────────────────────────────────────────────────────────
function CardView({ card, mini = false, selected = false, playing = false, landing = false, showName = false, revealed = true, onClick, onPointerDown, className: extraClass = "", style: extraStyle }) {
  const hue = hueOf(card);
  const energy = card.energy ?? card.clout;  // energy cost — falls back to power if not set
  const power  = card.clout;
  return (
    <div
      className={["card-view", mini?"card-mini":"", selected?"card-selected":"", playing?"card-playing":"", landing?"card-land":"", extraClass].filter(Boolean).join(" ")}
      style={{ "--ch": hue, cursor: onPointerDown ? "grab" : onClick ? "pointer" : "default", ...extraStyle }}
      onClick={onClick}
      onPointerDown={onPointerDown}
    >
      {/* Flip container — front face = full card, back face = uniform graphic */}
      <div className={`card-flip${revealed ? " is-revealed" : ""}`}>
        <div className="card-face card-front">
          <div className="card-clip">
            <div className="card-art">
              {card.imageUrl
                ? <img src={card.imageUrl} alt={card.name} />
                : <span className="card-emoji">{emojiOf(hue)}</span>}
            </div>
            <div className="card-vignette" />
            {showName && card.name && (
              <div className="card-nameplate">
                <div className="card-name-text">{card.name}</div>
              </div>
            )}
          </div>
          <div className="card-energy">{energy}</div>
          <div className="card-power">{power}</div>
        </div>
        <div className="card-face card-back">
          <CardBack mini={mini} />
        </div>
      </div>
    </div>
  );
}

function Zone({ zone, zoneRef, zoneIdx, state, dragOver, dragBlocked, scoreChanged, revealedIds, revealFx, powerFx, onSelectCard, playedThisTurnIds, onDragPlayerCard, onUnplayCard, draggingCardId }) {
  const pp = zonePower(zone.pCards, state, true,  zoneIdx) + klawBonusForZone(state||{zones:[]}, true,  zoneIdx);
  const ap = zonePower(zone.aCards, state, false, zoneIdx) + klawBonusForZone(state||{zones:[]}, false, zoneIdx);
  const winning = pp > ap ? "player" : ap > pp ? "ai" : "tied";

  // Build inline style: custom image takes priority; otherwise use placeholder gradient
  const zoneStyle = zone.bgImage
    ? { backgroundImage: `url(${zone.bgImage})` }
    : {
        "--zone-sky":     zone.sky     || "#0d1020",
        "--zone-horizon": zone.horizon || "#16244a",
        "--zone-ground":  zone.ground  || "#040408",
        "--zone-accent":  zone.accent  || "transparent",
      };

  return (
    <div
      ref={zoneRef}
      className={`zone${zone.bgImage ? " has-bg-image" : ""}${dragOver ? " drag-over" : ""}${dragBlocked ? " drag-blocked" : ""}`}
      style={zoneStyle}
    >
      <div className="zone-slot ai-slot">
        {zone.aCards.length
          ? zone.aCards.map(c => {
              const isRevealed = revealedIds?.has(c.id);
              const showFx     = revealFx && !revealFx.isPlayer && revealFx.cardId === c.id;
              const myDeltas = (powerFx || []).filter(d => d.cardId === c.id && d.side === "ai");
              return (
                <div key={c.id} className="zone-slot-cell">
                  <CardView card={c} mini landing
                    revealed={isRevealed}
                    onClick={isRevealed && onSelectCard ? () => onSelectCard(c.id) : undefined} />
                  {showFx && <RevealEffect snapName={revealFx.snapName} />}
                  {myDeltas.map(d => <PowerDeltaLabel key={d._id} delta={d.delta} />)}
                </div>
              );
            })
          : <span className="zone-empty">·</span>}
      </div>
      <div className={`zone-bar${winning==="player"?" winning-player":winning==="ai"?" winning-ai":""}`}>
        {/* AI score above the location name (closer to AI cards) */}
        <span className={`zone-score-hex${winning==="ai"?" leading-ai":""}${scoreChanged?" score-changed":""}`}>{ap}</span>
        <span className="zone-name">{zone.name}</span>
        <div className="zone-ability">{zone.ability}</div>
        {/* Player score below the location name (closer to player cards) */}
        <span className={`zone-score-hex${winning==="player"?" leading-player":""}${scoreChanged?" score-changed":""}`}>{pp}</span>
      </div>
      <div className="zone-slot player-slot">
        {zone.pCards.length
          ? zone.pCards.map(c => {
              const draggable = playedThisTurnIds?.has(c.id);
              const isDragged = draggingCardId === c.id;
              const isRevealed= revealedIds?.has(c.id);
              const showFx    = revealFx && revealFx.isPlayer && revealFx.cardId === c.id;
              const myDeltas = (powerFx || []).filter(d => d.cardId === c.id && d.side === "player");
              return (
                <div key={c.id} className="zone-slot-cell">
                  <CardView
                    card={c} mini landing
                    revealed={isRevealed}
                    className={draggable ? "card-uncommitted" : ""}
                    style={isDragged ? { opacity: 0.25, transition: "opacity 0.1s" } : undefined}
                    onPointerDown={draggable && onDragPlayerCard ? (e) => onDragPlayerCard(e, c.id) : undefined}
                    onClick={!draggable && onSelectCard ? () => onSelectCard(c.id) : undefined}
                  />
                  {showFx && <RevealEffect snapName={revealFx.snapName} />}
                  {myDeltas.map(d => <PowerDeltaLabel key={d._id} delta={d.delta} />)}
                </div>
              );
            })
          : <span className="zone-empty">·</span>}
      </div>
    </div>
  );
}

function HomeScreen({ onPlay, onCollection }) {
  return (
    <div className="screen home-screen">
      <div className="home-logo">
        <h1>ZANY</h1>
        <p className="home-sub">interdimensional card battles</p>
      </div>
      <div className="home-actions">
        <button className="btn btn-primary btn-big" onClick={onPlay}>▶ Play</button>
        <button className="btn btn-secondary" onClick={onCollection}>🃏 My Cards</button>
      </div>
    </div>
  );
}

function CollectionCard({ card, selected, onSelect }) {
  const hue = hueOf(card);
  const tiltRef = useTilt(10, 1.04);
  return (
    <div className="card-grid-item" onClick={onSelect}>
      <div ref={tiltRef} className={`coll-card card-tiltable${selected ? " coll-selected" : ""}`} style={{"--ch": hue}}>
        {card.imageUrl
          ? <img className="coll-card-art" src={card.imageUrl} alt={card.name} />
          : <div className="coll-card-emoji">{emojiOf(hue)}</div>}
        <div className="coll-card-overlay" />
        <div className="coll-shine" />
        <div className="coll-card-badge">{card.clout}</div><div className="coll-card-energy">{card.energy ?? card.clout}</div>
        <div className="coll-card-name">{card.name}</div>
      </div>
    </div>
  );
}

function CollectionScreen({ cards, onBack, onNew, onEdit, onDelete }) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const [selected, setSelected] = useState(null);

  const visible = cards.filter(c => {
    const ms = c.name.toLowerCase().includes(search.toLowerCase());
    const mf = filter === "all" ? true : filter === "ability" ? !!c.abilityText : filter === "no-art" ? !c.imageUrl : true;
    return ms && mf;
  });

  const selectedCard = cards.find(c => c.id === selected);

  return (
    <div className="screen" style={{paddingBottom: selected ? 80 : 0}} onClick={() => setSelected(null)}>
      <div className="screen-header" onClick={e => e.stopPropagation()}>
        <button className="btn btn-ghost" onClick={onBack}>← Back</button>
        <h2>Cards</h2>
        <button className="btn btn-primary" onClick={onNew}>+ New</button>
      </div>
      <div className="collection-toolbar" onClick={e => e.stopPropagation()}>
        <input className="search-input" placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)} />
        <div className="filter-tabs">
          {[["all","All"],["ability","Ability"],["no-art","No Art"]].map(([v,l]) => (
            <button key={v} className={`filter-tab${filter===v?" active":""}`} onClick={() => setFilter(v)}>{l}</button>
          ))}
        </div>
      </div>
      <div className="collection-count">{visible.length} / {cards.length}</div>
      <div className="card-grid" onClick={e => e.stopPropagation()}>
        {!visible.length && <div className="empty-state">No cards match.</div>}
        {visible.map(card => (
          <CollectionCard
            key={card.id}
            card={card}
            selected={selected === card.id}
            onSelect={e => { e.stopPropagation(); setSelected(p => p === card.id ? null : card.id); }}
          />
        ))}
      </div>
      {selectedCard && (
        <div className="coll-preview-backdrop" onClick={() => setSelected(null)}>
          <div className="coll-preview-stage" onClick={e => e.stopPropagation()}>
            <CardView card={selectedCard} showName className="coll-preview-card" />
            <div className="coll-preview-actions">
              <button className="btn btn-secondary" onClick={() => setSelected(null)}>Close</button>
              <button className="btn btn-primary" onClick={() => { setSelected(null); onEdit(selectedCard); }}>Edit</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function CardEditorScreen({ card, onSave, onBack }) {
  const [form, setForm] = useState({ name: card?.name||"", energy: card?.energy||3, clout: card?.clout||3, snapName: card?.snapName||"", abilityText: card?.abilityText||"", flavor: card?.flavor||"", imageUrl: card?.imageUrl||null });
  const [err, setErr] = useState("");
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const handleImg = e => { const f = e.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = ev => set("imageUrl", ev.target.result); r.readAsDataURL(f); };
  const handleSave = () => { if (!form.name.trim()) { setErr("A name is required."); return; } setErr(""); onSave({ id: card?.id || uid(), ...form, name: form.name.trim(), clout: Number(form.clout) }); };
  return (
    <div className="screen">
      <div className="screen-header">
        <button className="btn btn-ghost" onClick={onBack}>← Back</button>
        <h2>{card ? "Edit Card" : "New Card"}</h2>
        <button className="btn btn-primary" onClick={handleSave}>Save</button>
      </div>
      <div className="editor-layout">
        <div><CardView card={{ ...form, id: card?.id || "preview" }} /></div>
        <div className="editor-form">
          {err && <div className="form-err">{err}</div>}
          <label>Name<input value={form.name} onChange={e => set("name", e.target.value)} maxLength={30} /></label>
          <label>Clout (power 1–6)
            <div className="clout-row">{[1,2,3,4,5,6].map(n => <button key={n} className={`clout-btn${form.clout===n?" active":""}`} onClick={() => set("clout",n)}>{n}</button>)}</div>
          </label>
          <label>Ability
            <input
              type="text"
              placeholder="Snap reference (e.g. Black Panther)"
              value={form.snapName}
              onChange={e => set("snapName", e.target.value)}
            />
            <textarea
              placeholder="Ability text (e.g. On Reveal: Double this card's Power.)"
              value={form.abilityText}
              onChange={e => set("abilityText", e.target.value)}
              rows={2}
            />
          </label>
          <label>Flavor Text<input value={form.flavor} onChange={e => set("flavor", e.target.value)} maxLength={80} /></label>
          <label>Card Art (optional)<input type="file" accept="image/*" onChange={handleImg} /></label>
          {form.imageUrl && <button className="btn btn-sm btn-danger" style={{alignSelf:"flex-start"}} onClick={() => set("imageUrl",null)}>Remove Image</button>}
        </div>
      </div>
    </div>
  );
}

function CardPopup({ card, onDismiss, playable = true, onUnplay = null }) {
  const hue = hueOf(card);
  // ab dropped — using card.abilityText directly
  const [showBio, setShowBio] = useState(false);
  const tiltRef = useTilt(12, 1.0);
  return (
    <>
      <div className="card-popup-backdrop" />
      <div ref={tiltRef} className="card-popup card-tiltable" style={{"--ch": hue}}>
        <div className="popup-shine" />
        <button className="popup-close" onClick={onDismiss} aria-label="Close">✕</button>
        <div className="popup-art">
          {card.imageUrl
            ? <img src={card.imageUrl} alt={card.name} />
            : <div className="popup-art-emoji">{emojiOf(hue)}</div>}
        </div>
        {/* Badges OUTSIDE the art so they sit above the gradient overlay */}
        <div className="popup-badge energy-badge">{card.energy ?? card.clout}</div>
        <div className="popup-badge power-badge">{card.clout}</div>
        <div className="popup-body">
          <div className="popup-name-row">
            <div className="popup-name">{card.name}</div>
            {card.flavor && (
              <button
                className={`popup-info-btn${showBio ? " active" : ""}`}
                onClick={e => { e.stopPropagation(); setShowBio(s => !s); }}
                aria-label="Toggle bio"
              >i</button>
            )}
          </div>
          {/* Snap ability text on its own — old engine description is gone */}
          {card.abilityText && (
            <div className="popup-ability">
              ⚡ {card.abilityText}
              {card.snapName && <span className="popup-snap-credit"> · {card.snapName}</span>}
            </div>
          )}
          {showBio && card.flavor && <div className="popup-flavor">"{card.flavor}"</div>}
          {onUnplay && (
            <button className="popup-action-btn unplay" onClick={e => { e.stopPropagation(); onUnplay(); }}>
              ↶ Return to Hand
            </button>
          )}
        </div>
      </div>
    </>
  );
}

// ════════════════════════════════════════════════════════════════════
// CardBack — uniform back graphic for face-down cards (Marvel-Snap style)
// ════════════════════════════════════════════════════════════════════
function CardBack({ mini = false }) {
  return (
    <div className={`card-back-graphic${mini ? " card-back-mini" : ""}`}>
      <div className="card-back-frame">
        <div className="card-back-logo">Z</div>
        <div className="card-back-glyph">⬢</div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════
// RevealEffect — burst ring + floating ability label, shown briefly when
// a card's onReveal fires. Color/label come from snapName-based theming.
// ════════════════════════════════════════════════════════════════════
// Generic reveal effect — gold/cyan/red palette by ability category
function RevealEffect({ snapName }) {
  // Quick category sniff for the color
  const handler = snapName && SNAP_HANDLERS[snapName];
  let color = "#ffe066", glow = "rgba(255,224,102,0.7)", label = (snapName || "REVEAL").toUpperCase();
  if (snapName && handler) {
    const lc = snapName.toLowerCase();
    if (["aero","magneto","cannonball","nocturne","jeff","makkari"].some(n => lc.includes(n))) {
      color = "#5fd4ff"; glow = "rgba(95,212,255,0.7)";       // movement = cyan
    } else if (["cassandra","darkhawk","alioth","echo"].some(n => lc.includes(n))) {
      color = "#ff5e8a"; glow = "rgba(255,94,138,0.7)";       // debuff = pink/red
    } else if (["panther","silver","ant","gilgamesh","elsa","adam","nebula"].some(n => lc.includes(n))) {
      color = "#7eff5e"; glow = "rgba(126,255,94,0.7)";       // buff = green
    }
  }
  return (
    <>
      <div className="reveal-burst" style={{ borderColor: color, boxShadow: `0 0 24px ${glow}, inset 0 0 16px ${glow}` }} />
      <div className="reveal-burst-inner" style={{ background: `radial-gradient(circle, ${color}55 0%, transparent 70%)` }} />
      <div className="reveal-label" style={{ color, textShadow: `0 0 10px ${glow}, 0 2px 4px rgba(0,0,0,0.9)` }}>
        {label}
      </div>
    </>
  );
}

// ════════════════════════════════════════════════════════════════════
// PowerDeltaLabel — floating +N or -N number that rises and fades when
// a card's power changes from a Snap ability (Black Panther doubles,
// Cassandra Nova steals, etc.). Color-coded by sign.
// ════════════════════════════════════════════════════════════════════
function PowerDeltaLabel({ delta }) {
  const positive = delta > 0;
  const color = positive ? "#7eff5e" : "#ff5e8a";
  const glow  = positive ? "rgba(126,255,94,0.85)" : "rgba(255,94,138,0.85)";
  const sign  = positive ? "+" : "";
  return (
    <div className="power-delta-label" style={{
      color,
      textShadow: `0 0 10px ${glow}, 0 2px 4px rgba(0,0,0,0.95)`,
    }}>
      {sign}{delta}
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════
// MoveEffect — overlay that visualizes a card moving between zones.
// Renders a flashing border around source + destination, plus a dashed
// arrow drawn between them. Auto-fades over ~1s.
// ════════════════════════════════════════════════════════════════════
function MoveEffect({ event, zoneRefs }) {
  const fromRect = zoneRefs[event.fromZone]?.current?.getBoundingClientRect();
  const toRect   = zoneRefs[event.toZone]?.current?.getBoundingClientRect();
  if (!fromRect || !toRect) return null;

  // Side-aware Y: AI cards are in the top half, player cards in the bottom half.
  const yFrac = event.side === "player" ? 0.78 : 0.22;
  const fx = fromRect.left + fromRect.width / 2;
  const fy = fromRect.top  + fromRect.height * yFrac;
  const tx = toRect.left   + toRect.width  / 2;
  const ty = toRect.top    + toRect.height * yFrac;

  return (
    <div className="move-fx-layer" key={event._id}>
      <div className="move-flash move-flash-src" style={{
        left: fromRect.left, top: fromRect.top,
        width: fromRect.width, height: fromRect.height,
      }} />
      <div className="move-flash move-flash-dst" style={{
        left: toRect.left, top: toRect.top,
        width: toRect.width, height: toRect.height,
      }} />
      <svg className="move-arrow-svg" viewBox={`0 0 ${window.innerWidth} ${window.innerHeight}`} preserveAspectRatio="none">
        <defs>
          <marker id={`mfx-arrow-${event._id}`} markerWidth="10" markerHeight="10" refX="9" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#5fd4ff" />
          </marker>
        </defs>
        <line x1={fx} y1={fy} x2={tx} y2={ty}
              stroke="#5fd4ff" strokeWidth="3.5"
              strokeDasharray="8 5" strokeLinecap="round"
              markerEnd={`url(#mfx-arrow-${event._id})`} />
      </svg>
      <div className="move-label" style={{
        left: (fx + tx) / 2 - 40,
        top:  (fy + ty) / 2 - 16,
      }}>MOVED</div>
    </div>
  );
}

function DragGhost({ card, x, y }) {
  const hue = hueOf(card);
  return (
    <div className="drag-ghost" style={{ left: x, top: y, "--ch": hue, background: `hsl(${hue},16%,8%)` }}>
      <div className="card-art" style={{position:"absolute",inset:0,borderRadius:9}}>
        {card.imageUrl
          ? <img src={card.imageUrl} alt={card.name} style={{width:"100%",height:"100%",objectFit:"cover"}} />
          : <span style={{fontSize:"2.5rem",opacity:0.4}}>{emojiOf(hue)}</span>}
      </div>
      <div className="card-vignette" />
      <div className="card-energy" style={{position:"absolute",top:5,left:5,width:22,height:22,fontSize:"0.75rem"}}>{card.clout}</div>
      <div className="card-power"  style={{position:"absolute",bottom:5,right:5,width:22,height:22,fontSize:"0.75rem"}}>{card.clout}</div>
    </div>
  );
}


// ─── DeckPanel ────────────────────────────────────────────────────────────────
function DeckPanel({ title, icon, cards, onClose }) {
  return (
    <div className="deck-panel-backdrop" onClick={onClose}>
      <div className="deck-panel" onClick={e => e.stopPropagation()}>
        <div className="deck-panel-header">
          <span className="deck-panel-title">{icon} {title}</span>
          <span className="deck-panel-count">{cards.length} card{cards.length !== 1 ? "s" : ""}</span>
          <button className="deck-panel-close" onClick={onClose}>✕</button>
        </div>
        <div className="deck-panel-grid">
          {cards.length === 0
            ? <div className="deck-panel-empty">Nothing here yet</div>
            : cards.map((card, i) => (
                <div key={card.id || i} className="deck-panel-card-wrap">
                  <CardView card={card} mini revealed showName
                    style={{ width:"100%", height:"100%", borderRadius:"9px" }} />
                </div>
              ))
          }
        </div>
      </div>
    </div>
  );
}

// ─── ShuffleOverlay ───────────────────────────────────────────────────────────
function ShuffleOverlay({ deckSize, onDone }) {
  const [phase, setPhase] = useState("fan");   // fan → deal → done
  useEffect(() => {
    // Fan in: 0.8s, then trigger deal animation
    const t1 = setTimeout(() => setPhase("deal"), 700);
    // Deal anim runs ~1.4s (last card at 0.9s + 0.35s duration + buffer)
    const t2 = setTimeout(() => { onDone(); }, 2200);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  return (
    <div className="shuffle-overlay">
      <div className="shuffle-title">DEALING CARDS</div>
      <div className={`shuffle-deck-area shuffle-card-fan${phase === "deal" ? " shuffle-anim" : ""}`}>
        {[1,2,3,4,5].map(n => (
          <div key={n} className={`shuffle-card shuffle-card-${n}`}>🂠</div>
        ))}
      </div>
      <div className="shuffle-sub">SHUFFLING YOUR DECK</div>
      <div className="shuffle-count">{deckSize} CARDS · 6 TURNS</div>
    </div>
  );
}

function GameScreen({ cards, onBack }) {
  const [game, setGame]           = useState(() => initGame(cards));
  const [selected, setSelected]   = useState(null);   // card tapped for popup
  const [playingId, setPlayingId] = useState(null);
  const [deckPanel, setDeckPanel] = useState(null);   // null | "deck" | "discard" | "destroyed"

  // Drag state
  const [drag, setDrag]         = useState(null);  // { cardId, x, y }
  const [dragOver, setDragOver] = useState(null);  // zoneIdx
  const [debugLog, setDebugLog] = useState("idle"); // visible diagnostic
  const [revealFx, setRevealFx] = useState(null);   // {cardId, snapName, zoneIdx, isPlayer}
  const [moveFx,   setMoveFx]   = useState([]);     // [{type:"move", cardId, fromZone, toZone, side, _id}]
  const [powerFx,  setPowerFx]  = useState([]);     // [{cardId, side, zoneIdx, delta, _id}]
  const zoneRefs                = [useRef(), useRef(), useRef()];
  const dragRef                 = useRef(null);

  const inPlay   = game.phase === "play";
  const inReveal = game.phase === "reveal";
  const inEnd    = game.phase === "end";
  const inShuffle= game.phase === "shuffle";

  // Shuffle → play transition: deal HAND_SIZE cards one by one then start game
  const handleShuffleDone = () => {
    setGame(prev => {
      const s = JSON.parse(JSON.stringify(prev));
      s.playerHand = s.playerDeck.slice(0, HAND_SIZE);
      s.playerDeck = s.playerDeck.slice(HAND_SIZE);
      s.phase = "play";
      return s;
    });
  };

  // Reveal sequencer — runs after END TURN places AI cards face-down
  useEffect(() => {
    if (game.phase !== "reveal") return;

    // Build queue: priority player's plays first, in placement order
    const playerQ = (game.playerPlaysThisTurn || []).map(p => ({ ...p, isPlayer: true }));
    const aiQ     = (game.aiPlaysThisTurn     || []).map(p => ({ ...p, isPlayer: false }));
    const queue   = (game.priority === "player")
      ? [...playerQ, ...aiQ]
      : [...aiQ, ...playerQ];

    let cancelled = false;
    const timeouts = [];

    // Step the queue with delays
    let delay = 500;          // initial dramatic pause
    const flipTime = 700;     // per-card reveal interval

    queue.forEach((play, idx) => {
      timeouts.push(setTimeout(() => {
        if (cancelled) return;
        setGame(prev => {
          const s = JSON.parse(JSON.stringify(prev));
          const zone = s.zones[play.zoneIdx];
          const card = play.isPlayer
            ? zone.pCards.find(c => c.id === play.cardId)
            : zone.aCards.find(c => c.id === play.cardId);
          if (!card) return prev;
          if (!s.revealedIds.includes(card.id)) s.revealedIds.push(card.id);
          // Snapshot powers before the handler so we can diff after
          const before = _snapshotPowers(s);
          const result = applyReveal(card, play.zoneIdx, s, play.isPlayer);
          const after  = _snapshotPowers(result.state);
          const powerDeltas = _diffPowers(before, after);

          // Reveal-effect overlay (snapName label + glow on the card)
          setTimeout(() => {
            setRevealFx({
              cardId: play.cardId,
              snapName: card.snapName || "",
              zoneIdx: play.zoneIdx,
              isPlayer: play.isPlayer,
            });
          }, 220);

          // Move-effect overlays (one per moved card, staggered)
          if (result.fx && result.fx.length) {
            result.fx.forEach((ev, mi) => {
              const evWithId = { ...ev, _id: Date.now() + mi };
              setTimeout(() => setMoveFx(prev => [...prev, evWithId]), 380 + mi * 140);
              setTimeout(() => setMoveFx(prev => prev.filter(m => m._id !== evWithId._id)), 1500 + mi * 140);
            });
          }

          // Power-delta floating labels (+N / -N on each affected card)
          if (powerDeltas.length) {
            powerDeltas.forEach((d, di) => {
              const deltaWithId = { ...d, _id: Date.now() + 1000 + di };
              setTimeout(() => setPowerFx(prev => [...prev, deltaWithId]), 320 + di * 90);
              setTimeout(() => setPowerFx(prev => prev.filter(x => x._id !== deltaWithId._id)), 1300 + di * 90);
            });
          }
          return result.state;
        });
      }, delay));
      // Clear effect after animation
      timeouts.push(setTimeout(() => { if (!cancelled) setRevealFx(null); }, delay + 750));
      delay += flipTime;
    });

    // Final step: advance the turn + recompute priority for next turn
    timeouts.push(setTimeout(() => {
      if (cancelled) return;
      setGame(prev => {
        let s = JSON.parse(JSON.stringify(prev));
        s.playerPlaysThisTurn = [];
        s.aiPlaysThisTurn = [];
        // Compute priority for the upcoming turn based on current board state
        s.priority = computePriority(s, s.priority);
        if (s.turn >= TURNS) {
          s.phase = "end";
        } else {
          s.turn += 1;
          s.phase = "play";
          const draws = 1 + (s.bonusDraw || 0);
          s.bonusDraw = 0;
          for (let i = 0; i < draws; i++) {
            if (s.playerDeck.length) s.playerHand.push(s.playerDeck.shift());
            if (s.aiDeck.length)     s.aiHand.push(s.aiDeck.shift());
          }
        }
        return s;
      });
      setDebugLog("idle");
    }, delay + 400));

    return () => { cancelled = true; timeouts.forEach(clearTimeout); };
  }, [game.phase]);

  // Track which zone scores just changed so we can pulse them
  const prevScoresRef = useRef([null, null, null]);
  const [changedZones, setChangedZones] = useState(new Set());
  useEffect(() => {
    const newChanged = new Set();
    game.zones.forEach((z, i) => {
      const sig = `${zonePower(z.pCards, game, true, i) + klawBonusForZone(game, true, i)}|${zonePower(z.aCards, game, false, i) + klawBonusForZone(game, false, i)}`;
      if (prevScoresRef.current[i] !== null && prevScoresRef.current[i] !== sig) {
        newChanged.add(i);
      }
      prevScoresRef.current[i] = sig;
    });
    if (newChanged.size > 0) {
      setChangedZones(newChanged);
      const t = setTimeout(() => setChangedZones(new Set()), 600);
      return () => clearTimeout(t);
    }
  }, [game.zones]);



  // ── Hit-test which zone is under (x,y) ─────────────────────────────────────
  // Pure math: zones are always 3 equal columns in the upper-middle of screen.
  // No DOM lookups = bulletproof regardless of refs, transforms, z-index, etc.
  const hitZone = (x, y) => {
    if (typeof window === "undefined") return null;
    const w = window.innerWidth;
    const h = window.innerHeight;
    // Zones occupy the area between the top bar (~56px) and the bottom bar+hand
    // (~56px+120px = ~176px). Allow generous bounds for forgiving drops.
    const topLimit    = 40;
    const bottomLimit = h - 120;   // anything below this is hand area
    if (y < topLimit || y > bottomLimit) return null;
    // Three equal columns
    if (x < w / 3)     return 0;
    if (x < w * 2 / 3) return 1;
    return 2;
  };

  // ── Unplay a card placed this turn — return it to the hand and refund Flux ─
  const unplayCard = (cardId) => {
    setGame(prev => {
      const s = JSON.parse(JSON.stringify(prev));
      if (!(s.playerPlaysThisTurn || []).some(p => p.cardId === cardId)) return prev;
      // Find which zone has it
      let fromZone = -1;
      for (let i = 0; i < s.zones.length; i++) {
        if (s.zones[i].pCards.some(c => c.id === cardId)) { fromZone = i; break; }
      }
      if (fromZone === -1) return prev;
      const ci = s.zones[fromZone].pCards.findIndex(c => c.id === cardId);
      const card = s.zones[fromZone].pCards.splice(ci, 1)[0];
      s.playerHand.push(card);
      s.playerPlaysThisTurn = s.playerPlaysThisTurn.filter(p => p.cardId !== cardId);
      s.revealedIds = (s.revealedIds || []).filter(id => id !== cardId);
      return s;
    });
    setDebugLog(`Returned to hand`);
  };

  // ── Move a card placed this turn from one zone to another ──────────────────
  const moveCard = (cardId, toZone) => {
    setGame(prev => {
      const s = JSON.parse(JSON.stringify(prev));
      let fromZone = -1;
      for (let i = 0; i < s.zones.length; i++) {
        if (s.zones[i].pCards.some(c => c.id === cardId)) { fromZone = i; break; }
      }
      if (fromZone === -1 || fromZone === toZone) return prev;
      if (s.zones[toZone].pCards.length >= MAX_PER_SIDE) return prev;
      const ci = s.zones[fromZone].pCards.findIndex(c => c.id === cardId);
      const card = s.zones[fromZone].pCards.splice(ci, 1)[0];
      s.zones[toZone].pCards.push(card);
      s.playerPlaysThisTurn = (s.playerPlaysThisTurn || []).map(p =>
        p.cardId === cardId ? { ...p, zoneIdx: toZone } : p
      );
      return s;
    });
    setDebugLog(`Moved to zone ${toZone}`);
  };

  // ── Place a card in a zone immediately (Snap-style) ─────────────────────────
  // Card moves from hand to zone right away. Abilities don't trigger until END TURN.
  // Multiple plays allowed per turn — limited only by energy (Flux) budget.
  const placeCard = (cardId, zoneIdx) => {
    if (!inPlay) return;
    const card = game.playerHand.find(c => c.id === cardId);
    if (!card) return;
    const destroyedCount = (game.playerDestroyed || []).length;
    const hasDeath = (game.playerHand || []).some(c=>c.snapName==="Death") ||
                     game.zones.some(z=>z.pCards.some(c=>c.snapName==="Death"));
    const rawCost = card.energy ?? card.clout;
    const cost = hasDeath ? deathReducedCost(card, destroyedCount) : rawCost;
    const spent  = (game.playerPlaysThisTurn || []).reduce((s, p) => s + p.energy, 0);
    const budget = game.turn;
    if (cost > budget - spent) {
      setDebugLog(`Need ${cost} Flux — only ${budget - spent} left`);
      return;
    }
    if (game.zones[zoneIdx].pCards.length >= MAX_PER_SIDE) {
      setDebugLog(`Location full (${MAX_PER_SIDE} max)`);
      return;
    }
    setSelected(null);
    setPlayingId(cardId);
    setGame(prev => {
      const s = JSON.parse(JSON.stringify(prev));
      const ci = s.playerHand.findIndex(c => c.id === cardId);
      if (ci === -1) return prev;
      const placed = s.playerHand.splice(ci, 1)[0];
      s.zones[zoneIdx].pCards.push(placed);
      s.playerPlaysThisTurn = [...(s.playerPlaysThisTurn || []), { cardId, zoneIdx, energy: cost }];
      // Player cards stay face-down (NOT added to revealedIds) until END TURN.
      // They flip in priority order during the reveal sequence, same as AI cards.
      return s;
    });
    setTimeout(() => setPlayingId(null), 400);
  };

  // ── Drag start ─────────────────────────────────────────────────────────────
  // Strategy: do NOT preventDefault on pointerdown (breaks iOS touch sequence).
  // Use window-level listeners so events reach us even if a child intercepts.
  // preventDefault inside pointermove to block page scrolling during drag.
  const startDrag = (e, cardId, source = "hand") => {
    // source: "hand" = drag from hand, "zone" = drag a card placed this turn
    // Always allow drag-start so a tap can open the popup for ANY card.
    // Affordability + valid-source are re-checked at drop time.
    if (inEnd) {
      setDebugLog(`Game over`);
      return;
    }

    const startX = e.clientX;
    const startY = e.clientY;
    const TAP_THRESHOLD = 15;
    let moved = false;
    let lastEv = null;

    setSelected(null);
    dragRef.current = { cardId, x: startX, y: startY };
    setDrag({ cardId, x: startX, y: startY });
    setDebugLog(`DOWN ${startX|0},${startY|0}`);

    const onMove = ev => {
      if (ev.cancelable) ev.preventDefault();
      lastEv = ev;
      const x = ev.clientX, y = ev.clientY;
      if (!moved && (Math.abs(x - startX) > TAP_THRESHOLD || Math.abs(y - startY) > TAP_THRESHOLD)) {
        moved = true;
        setDebugLog(`DRAGGING (threshold passed)`);
      }
      dragRef.current = { cardId, x, y };
      setDrag({ cardId, x, y });
      if (moved) {
        const zi = hitZone(x, y);
        setDragOver(zi);
        setDebugLog(`MOVE ${x|0},${y|0} zone=${zi !== null ? zi : "none"}`);
      }
    };

    const onEnd = ev => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onEnd);
      window.removeEventListener("pointercancel", onEnd);

      // Use last move event for coords if pointerup has 0,0 (happens on iOS sometimes)
      const x = (ev.clientX || lastEv?.clientX || startX);
      const y = (ev.clientY || lastEv?.clientY || startY);
      const zi = moved ? hitZone(x, y) : null;

      setDebugLog(`UP ${x|0},${y|0} moved=${moved} zone=${zi !== null ? zi : "none"}`);

      dragRef.current = null;
      setDrag(null);
      setDragOver(null);

      if (!moved) {
        setSelected(p => p === cardId ? null : cardId);
      } else {
        // Branch on drag source
        if (source === "hand") {
          if (zi !== null) {
            // Hand → zone: place card (with affordability + full-zone checks)
            const card = game.playerHand.find(c => c.id === cardId);
            if (!card) {
              setDebugLog(`Not in hand`);
            } else if (game.zones[zi].pCards.length >= MAX_PER_SIDE) {
              setDebugLog(`Location full (${MAX_PER_SIDE} max)`);
            } else {
              const cost   = card.energy ?? card.clout;
              const spent  = (game.playerPlaysThisTurn || []).reduce((s, p) => s + p.energy, 0);
              const budget = game.turn;
              if (cost > budget - spent) {
                setDebugLog(`Need ${cost} Flux — only ${budget - spent} left`);
              } else if (!inPlay) {
                setDebugLog(`Wait for next turn`);
              } else {
                placeCard(cardId, zi);
              }
            }
          } else {
            setDebugLog(`Released outside`);
          }
        } else if (source === "zone") {
          // Zone card drag-back behavior
          if (!inPlay) {
            setDebugLog(`Wait for next turn`);
          } else if (zi === null) {
            unplayCard(cardId);
          } else {
            // Dropped on a zone: move (or no-op if same zone)
            moveCard(cardId, zi);
          }
        }
      }
    };

    window.addEventListener("pointermove", onMove, { passive: false });
    window.addEventListener("pointerup", onEnd);
    window.addEventListener("pointercancel", onEnd);
  };

  // End Turn: AI plays cards face-down → reveal sequence → advance turn.
  // Reveal order: player's plays first (priority), then AI's, in placement order.
  // Each reveal triggers that card's onReveal ability.
  const handleEndTurn = () => {
    if (!inPlay) return;
    setDebugLog("END TURN — AI playing, revealing in order");

    // Step 1: AI picks cards (greedy by energy, random zones), place face-down
    setGame(prev => {
      let s = JSON.parse(JSON.stringify(prev));
      const aiBudget = s.turn;
      let aiSpent = 0;
      const aiPlays = [];
      for (let attempt = 0; attempt < 3 && s.aiHand.length; attempt++) {
        const affordable = s.aiHand.filter(c => (c.energy ?? c.clout) <= aiBudget - aiSpent);
        if (!affordable.length) break;
        const openZones = [0, 1, 2].filter(zi => s.zones[zi].aCards.length < MAX_PER_SIDE);
        if (!openZones.length) break;
        const pick = affordable[Math.floor(Math.random() * affordable.length)];
        const zoneIdx = openZones[Math.floor(Math.random() * openZones.length)];
        const ci = s.aiHand.findIndex(c => c.id === pick.id);
        if (ci === -1) break;
        const card = s.aiHand.splice(ci, 1)[0];
        s.zones[zoneIdx].aCards.push(card);
        aiSpent += card.energy ?? card.clout;
        aiPlays.push({ cardId: card.id, zoneIdx });
      }
      s.aiPlaysThisTurn = aiPlays;   // remember for the reveal queue
      s.phase = "reveal";
      return s;
    });
  };

  const results = inEnd ? getResults(game) : null;
  const pWins   = results?.filter(r => r.winner === "player").length ?? 0;
  const aWins   = results?.filter(r => r.winner === "ai").length     ?? 0;
  // Overall winner uses the full Snap tiebreaker chain (locations → margin → total power)
  const overallWinner = inEnd ? computeWinner(game) : null;

  // Look up selected card anywhere: hand, player zones, AI zones
  const findCardAnywhere = id => {
    if (!id) return null;
    let c = game.playerHand.find(x => x.id === id);
    if (c) return c;
    for (const z of game.zones) {
      c = z.pCards.find(x => x.id === id) || z.aCards.find(x => x.id === id);
      if (c) return c;
    }
    return null;
  };
  const selectedCard  = findCardAnywhere(selected);
  const selectedInHand = selectedCard && game.playerHand.some(c => c.id === selected);
  const isDragging   = !!drag;

  return (
    <div className="screen game-screen">
      {/* DEBUG STATUS BAR — hidden in production. Set DEBUG_DRAG=true above to show. */}
      {DEBUG_DRAG && (
        <div className={`debug-status${dragOver !== null ? " debug-hit" : ""}`}>
          {debugLog}
        </div>
      )}

      {/* Top bar */}
      <div className="game-top">
        <div className={`player-pill${game.priority === "player" ? " has-priority" : ""}`}>
          <div className="player-avatar">🧑</div>
          <div className="player-name-block">
            <div className="player-name">YOU</div>
            <div className="hand-count">🃏 {game.playerHand?.length ?? 0}</div>
          </div>
        </div>
        <div className="energy-crystal">
          <div className="crystal-gem"><span>{game.turn - (game.playerPlaysThisTurn?.reduce((s,p)=>s+p.energy,0) || 0)}</span></div>
          <div className="crystal-label">FLUX · TURN {game.turn}/{TURNS}</div>
        </div>
        <div className={`player-pill${game.priority === "ai" ? " has-priority" : ""}`} style={{flexDirection:"row-reverse"}}>
          <div className="player-avatar">🤖</div>
          <div className="player-name-block">
            <div className="player-name">CPU</div>
            <div className="hand-count">🃏 {game.aiHand?.length ?? 0}</div>
          </div>
        </div>
      </div>

      {/* Zones */}
      <div className="zones-row">
        {game.zones.map((zone, i) => {
          const isOverThis = dragOver === i && isDragging && inPlay;
          const isFull     = zone.pCards.length >= MAX_PER_SIDE;
          return (
            <Zone
              key={zone.id} zone={zone} zoneRef={zoneRefs[i]} zoneIdx={i} state={game}
              dragOver={isOverThis && !isFull}
              dragBlocked={isOverThis && isFull}
              scoreChanged={changedZones.has(i)}
              revealedIds={new Set(game.revealedIds || [])}
              revealFx={revealFx && revealFx.zoneIdx === i ? revealFx : null}
              powerFx={powerFx.filter(d => d.zoneIdx === i)}
              onSelectCard={id => setSelected(p => p === id ? null : id)}
              playedThisTurnIds={new Set((game.playerPlaysThisTurn || []).map(p => p.cardId))}
              onDragPlayerCard={(e, cid) => startDrag(e, cid, "zone")}
              onUnplayCard={cid => unplayCard(cid)}
              draggingCardId={drag?.cardId}
            />
          );
        })}
      </div>

      {/* Bottom bar */}
      <div className="game-bottom">
        <button className="retreat-btn" onClick={onBack}>Retreat</button>
        <div className="status-hint">
          {inPlay && !isDragging && !game.playerPlay && "DRAG A CARD TO A LOCATION"}
          {inPlay && game.playerPlay && "TAP END TURN ▶"}
        </div>
        <button
          className={`end-turn-btn${(game.playerPlaysThisTurn?.length) ? " ready" : ""}`}
          onClick={handleEndTurn}
          disabled={!inPlay}
        >
          End Turn
          <div className="turn-counter">{game.turn} / {TURNS}</div>
        </button>
      </div>

      {/* Deck info pills — Snap-style deck / discard / destroyed buttons */}
      <div className="deck-info-row">
        <button className="deck-pill deck-pill-deck" onClick={() => setDeckPanel("deck")}>
          <span className="pill-icon">🂠</span>
          DECK
          <span className="pill-count">{game.playerDeck.length}</span>
        </button>
        <button className="deck-pill deck-pill-discard" onClick={() => setDeckPanel("discard")}>
          <span className="pill-icon">♻️</span>
          DISCARD
          <span className="pill-count">{(game.playerDiscard||[]).length}</span>
        </button>
        <button className="deck-pill deck-pill-destroy" onClick={() => setDeckPanel("destroyed")}>
          <span className="pill-icon">💀</span>
          DESTROYED
          <span className="pill-count">{(game.playerDestroyed||[]).length}</span>
        </button>
      </div>

      {/* Hand */}
      <div className="hand-area">
        <div className="hand-cards">
          {(() => {
            const spent  = (game.playerPlaysThisTurn || []).reduce((s, p) => s + p.energy, 0);
            const budget = game.turn;
            const remaining = budget - spent;
            const total = game.playerHand.length;
            // Dynamic slot width: shrink cards if hand is large, but never below 56px
            // Available width ≈ viewport - 24px margin. Cap card width at 92.
            const vw = (typeof window !== "undefined") ? window.innerWidth : 380;
            const slotW = Math.max(56, Math.min(92, Math.floor((vw - 24) / Math.max(total, 1)) - 4));
            return game.playerHand.map((card, i) => {
              const isSelected = selected === card.id;
              const isDragged  = drag?.cardId === card.id;
              const destroyedCt = (game.playerDestroyed || []).length;
              const hasDeathCard = game.zones.some(z=>z.pCards.some(c=>c.snapName==="Death")) || game.playerHand.some(c=>c.snapName==="Death");
              const cost       = hasDeathCard ? deathReducedCost(card, destroyedCt) : (card.energy ?? card.clout);
              const affordable = cost <= remaining;
              return (
                <div
                  key={card.id}
                  className="hand-slot"
                  style={{
                    "--slot-w": slotW + "px",
                    zIndex: isSelected || isDragged ? 60 : i,
                  }}
                >
                  <CardView
                    card={card}
                    selected={isSelected}
                    playing={playingId === card.id}
                    showName
                    style={{
                      opacity: isDragged ? 0.3 : (affordable ? 1 : 0.42),
                      filter: affordable ? undefined : "grayscale(0.6)",
                      transition: "opacity 0.15s, filter 0.15s, transform 0.2s",
                    }}
                    onPointerDown={e => startDrag(e, card.id)}
                  />
                </div>
              );
            });
          })()}
        </div>
      </div>

      {/* Drag ghost — follows finger/cursor */}
      {drag && (() => {
        let c = game.playerHand.find(x => x.id === drag.cardId);
        if (!c) for (const z of game.zones) { c = z.pCards.find(x => x.id === drag.cardId); if (c) break; }
        return c ? <DragGhost card={c} x={drag.x} y={drag.y} /> : null;
      })()}

      {/* Move-effect overlays — one per Snap-triggered move */}
      {moveFx.map(ev => <MoveEffect key={ev._id} event={ev} zoneRefs={zoneRefs} />)}

      {/* Card popup on tap — works for hand cards, zone cards (player & AI) */}
      {selectedCard && !drag && (() => {
        const isUncommitted = inPlay &&
          (game.playerPlaysThisTurn || []).some(p => p.cardId === selected);
        return (
          <CardPopup
            card={selectedCard}
            onDismiss={() => setSelected(null)}
            playable={selectedInHand && inPlay}
            onUnplay={isUncommitted ? () => { unplayCard(selected); setSelected(null); } : null}
          />
        );
      })()}

      {/* Shuffle / deal animation shown on game start */}
      {inShuffle && (
        <ShuffleOverlay
          deckSize={(game._fullPlayerDeck||game.playerDeck).length}
          onDone={handleShuffleDone}
        />
      )}

      {/* Deck info panel drawers */}
      {deckPanel === "deck" && (
        <DeckPanel
          title="Your Deck"
          icon="🂠"
          cards={game.playerDeck}
          onClose={() => setDeckPanel(null)}
        />
      )}
      {deckPanel === "discard" && (
        <DeckPanel
          title="Discard Pile"
          icon="♻️"
          cards={game.playerDiscard || []}
          onClose={() => setDeckPanel(null)}
        />
      )}
      {deckPanel === "destroyed" && (
        <DeckPanel
          title="Destroyed"
          icon="💀"
          cards={game.playerDestroyed || []}
          onClose={() => setDeckPanel(null)}
        />
      )}

      {/* End game overlay */}
      {inEnd && (
        <div className="result-overlay">
          <div className="result-card">
            <div className="result-title">
              {overallWinner === "player" ? "🎉 Victory!" : overallWinner === "ai" ? "💀 Defeated" : "🤝 Draw"}
            </div>
            <div className="result-sub">{pWins} – {aWins} Rifts</div>
            <div className="result-actions">
              <button className="btn btn-primary" onClick={() => { setGame(initGame(cards)); setSelected(null); }}>Play Again</button>
              <button className="btn btn-secondary" onClick={onBack}>Home</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── App ──────────────────────────────────────────────────────────────────────
export default function App() {
  useEffect(() => {
    const s = document.createElement("style"); s.textContent = GLOBAL_CSS; document.head.appendChild(s);
    return () => document.head.removeChild(s);
  }, []);

  // On first load: seed from spreadsheet cards.
  // We MERGE the SPREADSHEET data with stored data:
  //   - Stats (energy/clout/abilityId/flavor) ALWAYS come from SPREADSHEET_CARDS
  //     so balance changes flow to existing users without a manual cache clear.
  //   - User-uploaded imageUrl is preserved if they edited it via the editor.
  const [cards, setCards] = useState(() => {
    try {
      // One-time cleanup: drop the old v1 cache
      if (typeof STORAGE_KEY_OLD !== "undefined") localStorage.removeItem(STORAGE_KEY_OLD);
      const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
      const userImgs = {};
      const userExtra = {};
      if (stored && stored.length > 0) {
        stored.forEach(c => {
          // Preserve images the user has uploaded (anything not in CARD_IMAGES baseline)
          if (c.imageUrl && c.imageUrl !== CARD_IMAGES[c.id]) userImgs[c.id] = c.imageUrl;
          // Preserve any user-added cards not in SPREADSHEET_CARDS
          userExtra[c.id] = c;
        });
      }
      const merged = SPREADSHEET_CARDS.map(c => ({
        ...c,
        imageUrl: userImgs[c.id] || CARD_IMAGES[c.id] || c.imageUrl || null,
      }));
      // Append any user-added cards (IDs not in SPREADSHEET_CARDS)
      const baseIds = new Set(SPREADSHEET_CARDS.map(c => c.id));
      Object.values(userExtra).forEach(c => { if (!baseIds.has(c.id)) merged.push(c); });
      return merged;
    } catch {
      return SPREADSHEET_CARDS;
    }
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(cards)); }, [cards]);

  const [screen,  setScreen]  = useState("home");
  const [editing, setEditing] = useState(null);

  const saveCard   = card => { setCards(prev => { const i = prev.findIndex(c => c.id===card.id); return i!==-1 ? prev.map((c,j)=>j===i?card:c) : [...prev,card]; }); setScreen("collection"); setEditing(null); };
  const deleteCard = id   => setCards(prev => prev.filter(c => c.id !== id));

  if (screen==="game")       return <GameScreen cards={cards} onBack={() => setScreen("home")} />;
  if (screen==="collection") return <CollectionScreen cards={cards} onBack={() => setScreen("home")} onNew={() => { setEditing(null); setScreen("editor"); }} onEdit={c => { setEditing(c); setScreen("editor"); }} onDelete={deleteCard} />;
  if (screen==="editor")     return <CardEditorScreen card={editing} onSave={saveCard} onBack={() => setScreen("collection")} />;
  return <HomeScreen onPlay={() => setScreen("game")} onCollection={() => setScreen("collection")} />;
}
